parameters.jsCode:
const normalizarTexto = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const texto =
  normalizarTexto($json.message);

const estadoAnterior =
  $json.estadoPeluqueria || {};

// --------------------------------------------------
// Especie
// --------------------------------------------------

let especieDetectada = "";

if (
  /\b(?:perro|perra|canino|canina)\b/.test(
    texto
  )
) {
  especieDetectada = "perro";
} else if (
  /\b(?:gato|gata|felino|felina)\b/.test(
    texto
  )
) {
  especieDetectada = "gato";
} else if (
  /\b(?:conejo|coneja|huron|hurona|ave)\b/.test(
    texto
  )
) {
  especieDetectada = "otra";
}

const especie =
  especieDetectada ||
  String(
    estadoAnterior.especie || ""
  ).trim();

// --------------------------------------------------
// Servicio solicitado
// --------------------------------------------------

const mencionaServicioFueraCatalogo =
  /\b(?:bano\s+sanitario|corte\s+sanitario|deslanado|corte\s+de\s+unas|cortar\s+las\s+unas|limpieza\s+de\s+oidos|limpiar\s+los\s+oidos)\b/.test(
    texto
  );

let servicioFueraCatalogo = "";

if (
  /\b(?:bano\s+sanitario|corte\s+sanitario)\b/.test(
    texto
  )
) {
  servicioFueraCatalogo =
    "servicio_sanitario";
} else if (
  /\bdeslanado\b/.test(texto)
) {
  servicioFueraCatalogo =
    "deslanado";
} else if (
  /\b(?:corte\s+de\s+unas|cortar\s+las\s+unas)\b/.test(
    texto
  )
) {
  servicioFueraCatalogo =
    "corte_de_unas";
} else if (
  /\b(?:limpieza\s+de\s+oidos|limpiar\s+los\s+oidos)\b/.test(
    texto
  )
) {
  servicioFueraCatalogo =
    "limpieza_de_oidos";
}

let serviceIdDetectado = "";

const solicitaBanoYCorte =
  /\b(?:bano|lavado)\s+(?:y|con)\s+corte\b/.test(
    texto
  ) ||
  /\bcorte\s+(?:y|con)\s+(?:bano|lavado)\b/.test(
    texto
  );

const solicitaCorte =
  /\b(?:corte\s+de\s+pelo|servicio\s+de\s+corte)\b/.test(
    texto
  ) ||
  /\b(?:agendar|reservar)\s+(?:un\s+|el\s+)?corte\b/.test(
    texto
  ) ||
  /\b(?:quiero|necesito|quisiera|solicito)\s+(?:(?:agendar|reservar)\s+)?(?:un\s+|el\s+)?corte\b/.test(
    texto
  ) ||
  /^(?:un\s+|el\s+)?corte$/.test(
    texto
  );

const solicitaBano =
  /\b(?:bano|lavado)\b/.test(
    texto
  );

if (!mencionaServicioFueraCatalogo) {
  if (solicitaBanoYCorte) {
    serviceIdDetectado =
      "bano_y_corte";
  } else if (solicitaCorte) {
    serviceIdDetectado =
      "corte";
  } else if (solicitaBano) {
    serviceIdDetectado =
      "bano";
  }
}

const serviceId =
  serviceIdDetectado ||
  String(
    estadoAnterior.service_id || ""
  ).trim();

const nombresServicios = {
  bano: "Baño",
  corte: "Corte",
  bano_y_corte: "Baño y corte"
};

const nombreServicio =
  nombresServicios[serviceId] ||
  String(
    estadoAnterior.nombre_servicio || ""
  ).trim();

// --------------------------------------------------
// Tamaño
// --------------------------------------------------

let tamanoDetectado = "";

if (
  /\b(?:pequeno|pequena|chico|chica|mini)\b/.test(
    texto
  )
) {
  tamanoDetectado =
    "pequeno";
} else if (
  /\b(?:mediano|mediana)\b/.test(
    texto
  )
) {
  tamanoDetectado =
    "mediano";
} else if (
  /\b(?:grande|gigante)\b/.test(
    texto
  )
) {
  tamanoDetectado =
    "grande";
}

const tamano =
  tamanoDetectado ||
  String(
    estadoAnterior.tamano || ""
  ).trim();

// --------------------------------------------------
// Tipo de pelaje
// --------------------------------------------------

let tipoPelajeDetectado = "";

if (
  /\b(?:pelo|pelaje)\s+corto\b/.test(
    texto
  )
) {
  tipoPelajeDetectado =
    "corto";
} else if (
  /\b(?:pelo|pelaje)\s+largo\b/.test(
    texto
  )
) {
  tipoPelajeDetectado =
    "largo";
} else if (
  /\b(?:pelo|pelaje)\s+(?:rizado|ondulado)\b/.test(
    texto
  )
) {
  tipoPelajeDetectado =
    "rizado";
} else if (
  /\b(?:doble\s+capa|doble\s+pelaje)\b/.test(
    texto
  )
) {
  tipoPelajeDetectado =
    "doble_capa";
}

const tipoPelaje =
  tipoPelajeDetectado ||
  String(
    estadoAnterior.tipo_pelaje || ""
  ).trim();

// --------------------------------------------------
// Revisión humana
// --------------------------------------------------

let requiereRevisionHumana = false;
let motivoRevisionHumana = "";

if (
  especie &&
  especie !== "perro"
) {
  requiereRevisionHumana = true;
  motivoRevisionHumana =
    "especie_no_autorizada";
} else if (
  mencionaServicioFueraCatalogo
) {
  requiereRevisionHumana = true;
  motivoRevisionHumana =
    "servicio_fuera_catalogo";
}

// --------------------------------------------------
// Resultado
// --------------------------------------------------

return {
  json: {
    ...$json,

    interpretacionPeluqueria: {
      service_id:
        serviceId,

      nombre_servicio:
        nombreServicio,

      especie,

      tamano,

      tipo_pelaje:
        tipoPelaje,

      servicio_detectado:
        Boolean(serviceIdDetectado),

      tamano_detectado:
        Boolean(tamanoDetectado),

      pelaje_detectado:
        Boolean(tipoPelajeDetectado),

      menciona_servicio_fuera_catalogo:
        mencionaServicioFueraCatalogo,

      servicio_fuera_catalogo:
        servicioFueraCatalogo,

      requiere_revision_humana:
        requiereRevisionHumana,

      motivo_revision_humana:
        motivoRevisionHumana
    }
  }
};

const config =
  $json.peluqueriaConfig || {};

const interpretacion =
  $json.interpretacionPeluqueria || {};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const obtenerPrimerValor = (
  objeto,
  claves,
  valorPredeterminado
) => {
  for (const clave of claves) {
    if (
      objeto &&
      objeto[clave] !== undefined &&
      objeto[clave] !== null
    ) {
      return objeto[clave];
    }
  }

  return valorPredeterminado;
};

const obtenerBooleano = (
  objeto,
  claves,
  valorPredeterminado
) => {
  const valor =
    obtenerPrimerValor(
      objeto,
      claves,
      valorPredeterminado
    );

  if (typeof valor === "boolean") {
    return valor;
  }

  if (typeof valor === "string") {
    const normalizado =
      valor.trim().toLowerCase();

    if (normalizado === "true") {
      return true;
    }

    if (normalizado === "false") {
      return false;
    }
  }

  return Boolean(valor);
};

const obtenerNumero = (
  objeto,
  claves,
  valorPredeterminado = 0
) => {
  const valor =
    obtenerPrimerValor(
      objeto,
      claves,
      valorPredeterminado
    );

  const numero =
    Number(valor);

  return Number.isFinite(numero)
    ? numero
    : valorPredeterminado;
};

// --------------------------------------------------
// Datos interpretados o guardados
// --------------------------------------------------

const serviceId =
  String(
    interpretacion.service_id ||
    estadoAnterior.service_id ||
    ""
  ).trim();

const tamano =
  String(
    interpretacion.tamano ||
    estadoAnterior.tamano ||
    ""
  ).trim();

const tipoPelaje =
  String(
    interpretacion.tipo_pelaje ||
    estadoAnterior.tipo_pelaje ||
    ""
  ).trim();

const especieInterpretada =
  String(
    interpretacion.especie ||
    estadoAnterior.especie ||
    ""
  ).trim();

const especie =
  especieInterpretada ||
  "perro";

const especieAsumida =
  !especieInterpretada;

// --------------------------------------------------
// Buscar servicio dentro de la configuración
// --------------------------------------------------

const servicios =
  config.servicios ||
  config.services ||
  {};

let servicioConfig = null;

if (Array.isArray(servicios)) {
  servicioConfig =
    servicios.find((servicio) => {
      const id =
        String(
          servicio.service_id ||
          servicio.id ||
          ""
        ).trim();

      return id === serviceId;
    }) || null;
} else if (
  serviceId &&
  typeof servicios === "object"
) {
  servicioConfig =
    servicios[serviceId] || null;
}

const servicioConfigurado =
  Boolean(servicioConfig);

const servicioActivo =
  servicioConfigurado
    ? obtenerBooleano(
        servicioConfig,
        [
          "activo",
          "active",
          "habilitado"
        ],
        true
      )
    : false;

const nombreServicio =
  String(
    obtenerPrimerValor(
      servicioConfig,
      [
        "nombre_servicio",
        "nombre",
        "name"
      ],
      interpretacion.nombre_servicio ||
      estadoAnterior.nombre_servicio ||
      ""
    )
  ).trim();

// --------------------------------------------------
// Requisitos del servicio
// --------------------------------------------------

const requiereTamano =
  servicioConfigurado
    ? obtenerBooleano(
        servicioConfig,
        [
          "requiere_tamano",
          "tamano_requerido",
          "size_required"
        ],
        true
      )
    : true;

const requiereTipoPelaje =
  servicioConfigurado
    ? obtenerBooleano(
        servicioConfig,
        [
          "requiere_tipo_pelaje",
          "requiere_pelaje",
          "pelage_required"
        ],
        serviceId === "corte" ||
        serviceId === "bano_y_corte"
      )
    : false;

const intervaloInicioMinutos =
  servicioConfigurado
    ? obtenerNumero(
        servicioConfig,
        [
          "intervalo_inicio_minutos",
          "start_interval_minutes"
        ],
        obtenerNumero(
          config,
          [
            "intervalo_inicio_minutos_default",
            "intervalo_inicio_minutos",
            "default_start_interval_minutes"
          ],
          30
        )
      )
    : obtenerNumero(
        config,
        [
          "intervalo_inicio_minutos_default",
          "intervalo_inicio_minutos",
          "default_start_interval_minutes"
        ],
        30
      );

// --------------------------------------------------
// Especies autorizadas
// --------------------------------------------------

const especiesConfiguradas =
  servicioConfigurado
    ? obtenerPrimerValor(
        servicioConfig,
        [
          "especies_autorizadas",
          "especies_permitidas",
          "allowed_species"
        ],
        ["perro"]
      )
    : [];

const especiesAutorizadas =
  Array.isArray(especiesConfiguradas)
    ? especiesConfiguradas.map(
        (valor) =>
          String(valor)
            .trim()
            .toLowerCase()
      )
    : String(especiesConfiguradas || "")
        .split(",")
        .map(
          (valor) =>
            valor
              .trim()
              .toLowerCase()
        )
        .filter(Boolean);

const especieAutorizada =
  servicioConfigurado &&
  especiesAutorizadas.includes(
    especie.toLowerCase()
  );

// --------------------------------------------------
// Resolver duración según tamaño
// --------------------------------------------------

const resolverDuracionPorTamano = (
  servicio,
  tamanoBuscado
) => {
  if (
    !servicio ||
    !tamanoBuscado
  ) {
    return 0;
  }

  const reglas =
    obtenerPrimerValor(
      servicio,
      [
        "duraciones_por_tamano",
        "reglas_duracion",
        "duration_by_size",
        "duraciones"
      ],
      {}
    );

  if (Array.isArray(reglas)) {
    const regla =
      reglas.find((item) => {
        const tamanoRegla =
          String(
            item.tamano ||
            item.size ||
            ""
          )
            .trim()
            .toLowerCase();

        return (
          tamanoRegla ===
          tamanoBuscado.toLowerCase()
        );
      });

    if (!regla) {
      return 0;
    }

    return obtenerNumero(
      regla,
      [
        "duracion_minutos",
        "duracion",
        "minutes"
      ],
      0
    );
  }

  if (
    reglas &&
    typeof reglas === "object"
  ) {
    const regla =
      reglas[tamanoBuscado];

    if (
      typeof regla === "number" ||
      typeof regla === "string"
    ) {
      const numero =
        Number(regla);

      return Number.isFinite(numero)
        ? numero
        : 0;
    }

    if (
      regla &&
      typeof regla === "object"
    ) {
      return obtenerNumero(
        regla,
        [
          "duracion_minutos",
          "duracion",
          "minutes"
        ],
        0
      );
    }
  }

  return 0;
};

let duracionMinutos = 0;

if (
  servicioConfigurado &&
  requiereTamano &&
  tamano
) {
  duracionMinutos =
    resolverDuracionPorTamano(
      servicioConfig,
      tamano
    );
} else if (
  servicioConfigurado &&
  !requiereTamano
) {
  duracionMinutos =
    obtenerNumero(
      servicioConfig,
      [
        "duracion_minutos",
        "duracion_base_minutos",
        "duracion_base",
        "base_duration_minutes"
      ],
      0
    );
}

// --------------------------------------------------
// Datos que todavía faltan
// --------------------------------------------------

const datosFaltantes = [];

if (!serviceId) {
  datosFaltantes.push(
    "servicio"
  );
}

if (
  serviceId &&
  requiereTamano &&
  !tamano
) {
  datosFaltantes.push(
    "tamano"
  );
}

if (
  serviceId &&
  requiereTipoPelaje &&
  !tipoPelaje
) {
  datosFaltantes.push(
    "tipo_pelaje"
  );
}

// --------------------------------------------------
// Revisión humana
// --------------------------------------------------

let requiereRevisionHumana =
  interpretacion.requiere_revision_humana ===
  true;

let motivoRevisionHumana =
  String(
    interpretacion.motivo_revision_humana ||
    ""
  ).trim();

if (
  serviceId &&
  !servicioConfigurado
) {
  requiereRevisionHumana = true;
  motivoRevisionHumana =
    "servicio_no_configurado";
} else if (
  servicioConfigurado &&
  !servicioActivo
) {
  requiereRevisionHumana = true;
  motivoRevisionHumana =
    "servicio_inactivo";
} else if (
  servicioConfigurado &&
  !especieAutorizada
) {
  requiereRevisionHumana = true;
  motivoRevisionHumana =
    "especie_no_autorizada";
} else if (
  servicioConfigurado &&
  servicioActivo &&
  serviceId &&
  datosFaltantes.length === 0 &&
  duracionMinutos <= 0
) {
  requiereRevisionHumana = true;
  motivoRevisionHumana =
    "duracion_no_resuelta";
}

const servicioResuelto =
  Boolean(serviceId) &&
  servicioConfigurado &&
  servicioActivo &&
  especieAutorizada &&
  datosFaltantes.length === 0 &&
  duracionMinutos > 0 &&
  !requiereRevisionHumana;

// --------------------------------------------------
// Resultado
// --------------------------------------------------

return {
  json: {
    ...$json,

    resolucionServicioPeluqueria: {
      service_id:
        serviceId,

      nombre_servicio:
        nombreServicio,

      especie,

      especie_asumida:
        especieAsumida,

      tamano,

      tipo_pelaje:
        tipoPelaje,

      servicio_configurado:
        servicioConfigurado,

      servicio_activo:
        servicioActivo,

      especie_autorizada:
        especieAutorizada,

      requiere_tamano:
        requiereTamano,

      requiere_tipo_pelaje:
        requiereTipoPelaje,

      duracion_minutos:
        duracionMinutos,

      intervalo_inicio_minutos:
        intervaloInicioMinutos,

      datos_faltantes:
        datosFaltantes,

      requiere_revision_humana:
        requiereRevisionHumana,

      motivo_revision_humana:
        motivoRevisionHumana,

      servicio_resuelto:
        servicioResuelto
    }
  }
};

