parameters.jsCode:
const estadoAnterior =
  $json.estadoPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const datosFaltantes =
  Array.isArray(
    resolucion.datos_faltantes
  )
    ? resolucion.datos_faltantes
    : [];

const clinicId =
  String(
    $json.clinic_id ||
    estadoAnterior.clinic_id ||
    ""
  ).trim();

const sessionId =
  String(
    $json.session_id ||
    estadoAnterior.session_id ||
    ""
  ).trim();

const sessionKey =
  String(
    $json.session_key ||
    estadoAnterior.session_key ||
    (
      clinicId && sessionId
        ? `${clinicId}::${sessionId}`
        : ""
    )
  ).trim();

const normalizarOpcionesJson = (
  valor
) => {
  if (Array.isArray(valor)) {
    return JSON.stringify(valor);
  }

  const texto =
    String(valor || "").trim();

  return texto || "[]";
};

const estadoPeluqueriaGuardar = {
  session_key:
    sessionKey,

  clinic_id:
    clinicId,

  session_id:
    sessionId,

  estado_peluqueria:
    "esperando_datos_servicio",

  service_id:
    String(
      resolucion.service_id ||
      estadoAnterior.service_id ||
      ""
    ).trim(),

  nombre_servicio:
    String(
      resolucion.nombre_servicio ||
      estadoAnterior.nombre_servicio ||
      ""
    ).trim(),

  duracion_minutos:
    Number(
      resolucion.duracion_minutos ||
      estadoAnterior.duracion_minutos ||
      0
    ),

  nombre_tutor:
    String(
      estadoAnterior.nombre_tutor ||
      ""
    ).trim(),

  telefono:
    String(
      estadoAnterior.telefono ||
      ""
    ).trim(),

  nombre_mascota:
    String(
      estadoAnterior.nombre_mascota ||
      ""
    ).trim(),

  especie:
    String(
      resolucion.especie ||
      estadoAnterior.especie ||
      "perro"
    ).trim(),

  tamano:
    String(
      resolucion.tamano ||
      estadoAnterior.tamano ||
      ""
    ).trim(),

  tipo_pelaje:
    String(
      resolucion.tipo_pelaje ||
      estadoAnterior.tipo_pelaje ||
      ""
    ).trim(),

  fecha_pendiente:
    String(
      estadoAnterior.fecha_pendiente ||
      ""
    ).trim(),

  hora_pendiente:
    String(
      estadoAnterior.hora_pendiente ||
      ""
    ).trim(),

  start_time:
    String(
      estadoAnterior.start_time ||
      ""
    ).trim(),

  end_time:
    String(
      estadoAnterior.end_time ||
      ""
    ).trim(),

  opciones_json:
    normalizarOpcionesJson(
      estadoAnterior.opciones_json
    ),

  updated_at:
    new Date().toISOString()
};

return {
  json: {
    ...$json,

    datosFaltantesServicio:
      datosFaltantes,

    estadoPeluqueriaGuardar
  }
};

