})() }}

parameters.jsCode:
const normalizarEspacios = (valor) =>
  String(valor || "")
    .replace(/\s+/g, " ")
    .trim();

const normalizarBusqueda = (valor) =>
  normalizarEspacios(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

const limpiarNombre = (valor) =>
  normalizarEspacios(valor)
    .replace(
      /^(?:el|la|un|una)\s+/i,
      ""
    )
    .replace(
      /[.,;:!?]+$/g,
      ""
    )
    .trim();

const mensajeOriginal =
  String($json.message || "");

const texto =
  normalizarBusqueda(
    mensajeOriginal
  );

const estadoAnterior =
  $json.estadoPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

// --------------------------------------------------
// Nombre del tutor
// --------------------------------------------------

const finNombreTutor =
  "(?=\\s*(?:,|;|\\.|:|!|\\?|$)|" +
  "\\s+(?:y\\s+)?(?:mascota|telefono|teléfono|celular|numero|número|contacto)\\b)";

const patronesTutor = [
  new RegExp(
    "(?:me\\s+llamo|mi\\s+nombre\\s+es|soy)\\s+" +
    "([a-záéíóúñü'-]+(?:\\s+[a-záéíóúñü'-]+){0,3}?)" +
    finNombreTutor,
    "i"
  ),

  new RegExp(
    "(?:nombre\\s+del\\s+tutor|tutor(?:a)?)" +
    "(?:\\s*(?::|-)\\s*|\\s+es\\s+|\\s+)" +
    "([a-záéíóúñü'-]+(?:\\s+[a-záéíóúñü'-]+){0,3}?)" +
    finNombreTutor,
    "i"
  )
];

let nombreTutorDetectado = "";

for (const patron of patronesTutor) {
  const coincidencia =
    mensajeOriginal.match(patron);

  if (
    coincidencia &&
    coincidencia[1]
  ) {
    nombreTutorDetectado =
      limpiarNombre(
        coincidencia[1]
      );

    break;
  }
}

const nombreTutor =
  nombreTutorDetectado ||
  String(
    estadoAnterior.nombre_tutor || ""
  ).trim();

// --------------------------------------------------
// Nombre de la mascota
// --------------------------------------------------

const finNombreMascota =
  "(?=\\s*(?:,|;|\\.|:|!|\\?|$)|" +
  "\\s+(?:y\\s+)?(?:mi\\s+)?(?:telefono|teléfono|celular|numero|número|contacto)\\b)";

const patronesMascota = [
  new RegExp(
    "(?:mi\\s+(?:perro|perra|mascota)\\s+se\\s+llama)\\s+" +
    "([a-záéíóúñü'-]+(?:\\s+[a-záéíóúñü'-]+){0,2}?)" +
    finNombreMascota,
    "i"
  ),

  new RegExp(
    "(?:se\\s+llama)\\s+" +
    "([a-záéíóúñü'-]+(?:\\s+[a-záéíóúñü'-]+){0,2}?)" +
    finNombreMascota,
    "i"
  ),

  new RegExp(
    "(?:nombre\\s+de\\s+la\\s+mascota|mascota)" +
    "(?:\\s*(?::|-)\\s*|\\s+es\\s+|\\s+se\\s+llama\\s+|\\s+)" +
    "([a-záéíóúñü'-]+(?:\\s+[a-záéíóúñü'-]+){0,2}?)" +
    finNombreMascota,
    "i"
  )
];

let nombreMascotaDetectado = "";

for (const patron of patronesMascota) {
  const coincidencia =
    mensajeOriginal.match(patron);

  if (
    coincidencia &&
    coincidencia[1]
  ) {
    nombreMascotaDetectado =
      limpiarNombre(
        coincidencia[1]
      );

    break;
  }
}

const nombreMascota =
  nombreMascotaDetectado ||
  String(
    estadoAnterior.nombre_mascota || ""
  ).trim();

// --------------------------------------------------
// Teléfono móvil chileno
// --------------------------------------------------

const normalizarTelefonoChile = (
  valor
) => {
  const digitos =
    String(valor || "")
      .replace(/\D/g, "");

  if (
    /^569\d{8}$/.test(digitos)
  ) {
    return `+${digitos}`;
  }

  if (
    /^09\d{8}$/.test(digitos)
  ) {
    return `+56${digitos.slice(1)}`;
  }

  if (
    /^9\d{8}$/.test(digitos)
  ) {
    return `+56${digitos}`;
  }

  return "";
};

const candidatosTelefono =
  mensajeOriginal.match(
    /(?:\+?56[\s-]?)?(?:0?9)[\s-]?\d{4}[\s-]?\d{4}/g
  ) || [];

let telefonoDetectado = "";

for (
  const candidato of candidatosTelefono
) {
  const telefonoNormalizado =
    normalizarTelefonoChile(
      candidato
    );

  if (telefonoNormalizado) {
    telefonoDetectado =
      telefonoNormalizado;

    break;
  }
}

const telefonoGuardado =
  normalizarTelefonoChile(
    estadoAnterior.telefono
  );

const telefono =
  telefonoDetectado ||
  telefonoGuardado;

// --------------------------------------------------
// Consolidar servicio resuelto
// --------------------------------------------------

const serviceId =
  String(
    resolucion.service_id ||
    estadoAnterior.service_id ||
    ""
  ).trim();

const nombreServicio =
  String(
    resolucion.nombre_servicio ||
    estadoAnterior.nombre_servicio ||
    ""
  ).trim();

const especie =
  String(
    resolucion.especie ||
    estadoAnterior.especie ||
    "perro"
  ).trim();

const tamano =
  String(
    resolucion.tamano ||
    estadoAnterior.tamano ||
    ""
  ).trim();

const tipoPelaje =
  String(
    resolucion.tipo_pelaje ||
    estadoAnterior.tipo_pelaje ||
    ""
  ).trim();

const duracionMinutos =
  Number(
    resolucion.duracion_minutos ||
    estadoAnterior.duracion_minutos ||
    0
  );

const intervaloInicioMinutos =
  Number(
    resolucion.intervalo_inicio_minutos ||
    30
  );

// --------------------------------------------------
// Datos mínimos faltantes
// --------------------------------------------------

const datosFaltantes = [];

if (!nombreTutor) {
  datosFaltantes.push(
    "nombre_tutor"
  );
}

if (!nombreMascota) {
  datosFaltantes.push(
    "nombre_mascota"
  );
}

if (!telefono) {
  datosFaltantes.push(
    "telefono"
  );
}

const datosMinimosCompletos =
  datosFaltantes.length === 0;

// --------------------------------------------------
// Resultado
// --------------------------------------------------

return {
  json: {
    ...$json,

    datosReservaPeluqueria: {
      service_id:
        serviceId,

      nombre_servicio:
        nombreServicio,

      duracion_minutos:
        duracionMinutos,

      intervalo_inicio_minutos:
        intervaloInicioMinutos,

      nombre_tutor:
        nombreTutor,

      nombre_mascota:
        nombreMascota,

      telefono,

      especie,

      tamano,

      tipo_pelaje:
        tipoPelaje,

      nombre_tutor_detectado:
        Boolean(nombreTutorDetectado),

      nombre_mascota_detectado:
        Boolean(nombreMascotaDetectado),

      telefono_detectado:
        Boolean(telefonoDetectado),

      datos_faltantes:
        datosFaltantes,

      datos_minimos_completos:
        datosMinimosCompletos
    }
  }
};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const datosFaltantes =
  Array.isArray(
    datosReserva.datos_faltantes
  )
    ? datosReserva.datos_faltantes
    : [];

const clinicId =
  String(
    $json.clinic_id ||
    estadoAnterior.clinic_id ||
    ""
  ).trim();

const sessionId =
  String(
    $json.session_id ||
    estadoAnterior.session_id ||
    ""
  ).trim();

const sessionKey =
  String(
    $json.session_key ||
    estadoAnterior.session_key ||
    (
      clinicId && sessionId
        ? `${clinicId}::${sessionId}`
        : ""
    )
  ).trim();

const normalizarOpcionesJson = (
  valor
) => {
  if (Array.isArray(valor)) {
    return JSON.stringify(valor);
  }

  const texto =
    String(valor || "").trim();

  return texto || "[]";
};

const estadoPeluqueriaGuardar = {
  session_key:
    sessionKey,

  clinic_id:
    clinicId,

  session_id:
    sessionId,

  estado_peluqueria:
    "esperando_datos_minimos",

  service_id:
    String(
      datosReserva.service_id ||
      estadoAnterior.service_id ||
      ""
    ).trim(),

  nombre_servicio:
    String(
      datosReserva.nombre_servicio ||
      estadoAnterior.nombre_servicio ||
      ""
    ).trim(),

  duracion_minutos:
    Number(
      datosReserva.duracion_minutos ||
      estadoAnterior.duracion_minutos ||
      0
    ),

  nombre_tutor:
    String(
      datosReserva.nombre_tutor ||
      estadoAnterior.nombre_tutor ||
      ""
    ).trim(),

  telefono:
    String(
      datosReserva.telefono ||
      estadoAnterior.telefono ||
      ""
    ).trim(),

  nombre_mascota:
    String(
      datosReserva.nombre_mascota ||
      estadoAnterior.nombre_mascota ||
      ""
    ).trim(),

  especie:
    String(
      datosReserva.especie ||
      estadoAnterior.especie ||
      "perro"
    ).trim(),

  tamano:
    String(
      datosReserva.tamano ||
      estadoAnterior.tamano ||
      ""
    ).trim(),

  tipo_pelaje:
    String(
      datosReserva.tipo_pelaje ||
      estadoAnterior.tipo_pelaje ||
      ""
    ).trim(),

  fecha_pendiente:
    String(
      estadoAnterior.fecha_pendiente ||
      ""
    ).trim(),

  hora_pendiente:
    String(
      estadoAnterior.hora_pendiente ||
      ""
    ).trim(),

  start_time:
    String(
      estadoAnterior.start_time ||
      ""
    ).trim(),

  end_time:
    String(
      estadoAnterior.end_time ||
      ""
    ).trim(),

  opciones_json:
    normalizarOpcionesJson(
      estadoAnterior.opciones_json
    ),

  updated_at:
    new Date().toISOString()
};

return {
  json: {
    ...$json,

    datosFaltantesReservaPeluqueria:
      datosFaltantes,

    estadoPeluqueriaGuardar
  }
};;

