parameters.jsCode:
const normalizar = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const DateTime =
  $now.constructor;

const mensaje =
  normalizar($json.message);

const config =
  $json.peluqueriaConfig || {};

const estadoPrevio =
  $json.estadoPeluqueria || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucionServicio =
  $json.resolucionServicioPeluqueria || {};

const zonaHoraria =
  config.zona_horaria ||
  "America/Santiago";

const duracionMinutos =
  Number(
    datosReserva.duracion_minutos ||
    resolucionServicio.duracion_minutos ||
    estadoPrevio.duracion_minutos ||
    0
  );

const cantidadAlternativas =
  Number(
    config.cantidad_alternativas ||
    config.max_alternativas ||
    3
  );

const ahora =
  $now.setZone(zonaHoraria);

// --------------------------------------------------
// Alternativas guardadas
// --------------------------------------------------

const obtenerOpcionesGuardadas = () => {
  const valor =
    estadoPrevio.opciones_json;

  if (Array.isArray(valor)) {
    return valor;
  }

  try {
    const resultado =
      JSON.parse(valor || "[]");

    if (Array.isArray(resultado)) {
      return resultado;
    }

    if (
      Array.isArray(
        resultado?.opcionesPeluqueria
      )
    ) {
      return (
        resultado.opcionesPeluqueria
      );
    }

    if (
      Array.isArray(
        resultado?.opcionesAgenda
      )
    ) {
      return resultado.opcionesAgenda;
    }
  } catch {}

  return [];
};

const opcionesGuardadas =
  obtenerOpcionesGuardadas();

const detectarOpcionSeleccionada =
  () => {
    const limite =
      Math.max(
        cantidadAlternativas,
        1
      );

    const numeroDirecto =
      mensaje.match(
        new RegExp(
          `^([1-${limite}])\\s*[.)]?$`
        )
      );

    if (numeroDirecto) {
      return Number(
        numeroDirecto[1]
      );
    }

    const numeroEnFrase =
      mensaje.match(
        new RegExp(
          `\\b(?:opcion|alternativa|elijo|escojo|prefiero|selecciono|quiero)` +
          `(?:\\s+la)?(?:\\s+opcion)?\\s+([1-${limite}])\\b`
        )
      );

    if (numeroEnFrase) {
      return Number(
        numeroEnFrase[1]
      );
    }

    const equivalencias = {
      primera: 1,
      segunda: 2,
      tercera: 3,
      uno: 1,
      dos: 2,
      tres: 3
    };

    for (
      const [palabra, numero]
      of Object.entries(
        equivalencias
      )
    ) {
      if (
        numero <= limite &&
        new RegExp(
          `\\b${palabra}\\b`
        ).test(mensaje)
      ) {
        return numero;
      }
    }

    return null;
  };

const opcionSeleccionada =
  detectarOpcionSeleccionada();

if (opcionSeleccionada) {
  const opcion =
    opcionesGuardadas.find(
      (item, indice) =>
        Number(item.numero) ===
          opcionSeleccionada ||
        indice + 1 ===
          opcionSeleccionada
    );

  const inicioOpcion =
    opcion?.inicio ||
    opcion?.startTime ||
    opcion?.start_time ||
    "";

  if (inicioOpcion) {
    const inicio =
      DateTime.fromISO(
        inicioOpcion,
        {
          zone: zonaHoraria
        }
      );

    const finOpcionTexto =
      opcion?.fin ||
      opcion?.endTime ||
      opcion?.end_time ||
      "";

    const fin =
      finOpcionTexto
        ? DateTime.fromISO(
            finOpcionTexto,
            {
              zone: zonaHoraria
            }
          )
        : inicio.plus({
            minutes:
              duracionMinutos
          });

    return {
      json: {
        ...$json,

        estadoPeluqueria: {
          ...estadoPrevio,

          start_time:
            inicio.toISO(),

          end_time:
            fin.toISO(),

          fecha_pendiente:
            inicio.toISODate(),

          hora_pendiente:
            inicio.toFormat(
              "HH:mm"
            )
        },

        startTime:
          inicio.toISO(),

        endTime:
          fin.toISO(),

        interpretacionHorarioPeluqueria: {
          origen:
            "opcion_guardada",

          opcion_seleccionada:
            opcionSeleccionada,

          fecha_detectada:
            inicio.toISODate(),

          hora_detectada:
            inicio.toFormat(
              "HH:mm"
            ),

          fecha_detectada_en_mensaje:
            false,

          hora_detectada_en_mensaje:
            false,

          tiene_fecha_hora:
            true,

          fecha_hora_pasada:
            inicio <= ahora
        }
      }
    };
  }
}

// --------------------------------------------------
// Interpretación de fecha
// --------------------------------------------------

const meses = {
  enero: 1,
  febrero: 2,
  marzo: 3,
  abril: 4,
  mayo: 5,
  junio: 6,
  julio: 7,
  agosto: 8,
  septiembre: 9,
  setiembre: 9,
  octubre: 10,
  noviembre: 11,
  diciembre: 12
};

const diasSemana = {
  domingo: 7,
  lunes: 1,
  martes: 2,
  miercoles: 3,
  jueves: 4,
  viernes: 5,
  sabado: 6
};

let fechaDetectada = null;

const fechaExplicita =
  mensaje.match(
    /\b(\d{1,2})\s+de\s+([a-z]+)(?:\s+de\s+(\d{4}))?\b/
  );

const fechaNumerica =
  mensaje.match(
    /\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?\b/
  );

if (fechaExplicita) {
  const dia =
    Number(fechaExplicita[1]);

  const mes =
    meses[fechaExplicita[2]];

  const anio =
    fechaExplicita[3]
      ? Number(
          fechaExplicita[3]
        )
      : ahora.year;

  if (mes) {
    const candidata =
      ahora.set({
        year: anio,
        month: mes,
        day: dia
      });

    if (candidata.isValid) {
      fechaDetectada =
        candidata;
    }
  }
} else if (fechaNumerica) {
  const dia =
    Number(fechaNumerica[1]);

  const mes =
    Number(fechaNumerica[2]);

  let anio =
    fechaNumerica[3]
      ? Number(fechaNumerica[3])
      : ahora.year;

  if (
    anio >= 0 &&
    anio < 100
  ) {
    anio += 2000;
  }

  const candidata =
    ahora.set({
      year: anio,
      month: mes,
      day: dia
    });

  if (candidata.isValid) {
    fechaDetectada =
      candidata;
  }
} else if (
  /\bpasado\s+manana\b/.test(
    mensaje
  )
) {
  fechaDetectada =
    ahora.plus({
      days: 2
    });
} else if (
  /\bmanana\b/.test(mensaje)
) {
  fechaDetectada =
    ahora.plus({
      days: 1
    });
} else if (
  /\bhoy\b/.test(mensaje)
) {
  fechaDetectada =
    ahora;
} else {
  for (
    const [nombreDia, numeroDia]
    of Object.entries(
      diasSemana
    )
  ) {
    if (
      new RegExp(
        `\\b${nombreDia}\\b`
      ).test(mensaje)
    ) {
      let diasHastaFecha =
        (
          numeroDia -
          ahora.weekday +
          7
        ) % 7;

      if (
        diasHastaFecha === 0 &&
        /\bproximo\b/.test(
          mensaje
        )
      ) {
        diasHastaFecha = 7;
      }

      fechaDetectada =
        ahora.plus({
          days:
            diasHastaFecha
        });

      break;
    }
  }
}

// --------------------------------------------------
// Interpretación de hora
// --------------------------------------------------

const horaConPalabras =
  mensaje.match(
    /\b(?:a\s+las?|para\s+las?)\s+(\d{1,2})(?:(?::(\d{2}))|\s+y\s+(media|cuarto|\d{1,2}))?\s*(?:de\s+la\s+)?(manana|tarde|noche|am|pm)?\b/
  );

const horaConAmPm =
  mensaje.match(
    /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/
  );

const horaConDosPuntos =
  mensaje.match(
    /\b(\d{1,2}):(\d{2})\b/
  );

let horaDetectada = null;
let minutoDetectado = null;
let periodo = "";

if (horaConPalabras) {
  horaDetectada =
    Number(
      horaConPalabras[1]
    );

  if (horaConPalabras[2]) {
    minutoDetectado =
      Number(
        horaConPalabras[2]
      );
  } else if (
    horaConPalabras[3] ===
    "media"
  ) {
    minutoDetectado = 30;
  } else if (
    horaConPalabras[3] ===
    "cuarto"
  ) {
    minutoDetectado = 15;
  } else if (
    horaConPalabras[3]
  ) {
    minutoDetectado =
      Number(
        horaConPalabras[3]
      );
  } else {
    minutoDetectado = 0;
  }

  periodo =
    horaConPalabras[4] || "";
} else if (horaConAmPm) {
  horaDetectada =
    Number(horaConAmPm[1]);

  minutoDetectado =
    horaConAmPm[2]
      ? Number(
          horaConAmPm[2]
        )
      : 0;

  periodo =
    horaConAmPm[3] || "";
} else if (horaConDosPuntos) {
  horaDetectada =
    Number(
      horaConDosPuntos[1]
    );

  minutoDetectado =
    Number(
      horaConDosPuntos[2]
    );
}

if (
  horaDetectada !== null &&
  minutoDetectado !== null
) {
  if (
    (
      periodo === "tarde" ||
      periodo === "noche" ||
      periodo === "pm"
    ) &&
    horaDetectada < 12
  ) {
    horaDetectada += 12;
  }

  if (
    (
      periodo === "manana" ||
      periodo === "am"
    ) &&
    horaDetectada === 12
  ) {
    horaDetectada = 0;
  }

  if (
    periodo === "noche" &&
    horaDetectada === 12
  ) {
    horaDetectada = 0;
  }

  if (
    !periodo &&
    horaDetectada >= 1 &&
    horaDetectada <= 6
  ) {
    horaDetectada += 12;
  }

  if (
    horaDetectada < 0 ||
    horaDetectada > 23 ||
    minutoDetectado < 0 ||
    minutoDetectado > 59
  ) {
    horaDetectada = null;
    minutoDetectado = null;
  }
}

const fechaDetectadaEnMensaje =
  Boolean(fechaDetectada);

const horaDetectadaEnMensaje =
  horaDetectada !== null &&
  minutoDetectado !== null;

// --------------------------------------------------
// Recuperar fecha y hora pendientes
// --------------------------------------------------

let fechaPendiente =
  fechaDetectada
    ? fechaDetectada.toISODate()
    : String(
        estadoPrevio.fecha_pendiente ||
        ""
      ).trim();

let horaPendiente =
  horaDetectadaEnMensaje
    ? (
        String(
          horaDetectada
        ).padStart(2, "0") +
        ":" +
        String(
          minutoDetectado
        ).padStart(2, "0")
      )
    : String(
        estadoPrevio.hora_pendiente ||
        ""
      ).trim();

const startTimeAnterior =
  String(
    estadoPrevio.start_time ||
    ""
  ).trim();

const inicioAnterior =
  startTimeAnterior
    ? DateTime.fromISO(
        startTimeAnterior,
        {
          zone: zonaHoraria
        }
      )
    : null;

if (
  !fechaPendiente &&
  inicioAnterior?.isValid
) {
  fechaPendiente =
    inicioAnterior.toISODate();
}

if (
  !horaPendiente &&
  inicioAnterior?.isValid
) {
  horaPendiente =
    inicioAnterior.toFormat(
      "HH:mm"
    );
}

// --------------------------------------------------
// Construir inicio y término
// --------------------------------------------------

let startTime = "";
let endTime = "";

let origen =
  "sin_fecha_hora";

if (
  fechaPendiente &&
  horaPendiente
) {
  const partesHora =
    horaPendiente.match(
      /^(\d{2}):(\d{2})$/
    );

  if (partesHora) {
    const horaFinal =
      Number(partesHora[1]);

    const minutoFinal =
      Number(partesHora[2]);

    const fechaBase =
      DateTime.fromISO(
        fechaPendiente,
        {
          zone: zonaHoraria
        }
      );

    if (
      fechaBase.isValid &&
      horaFinal >= 0 &&
      horaFinal <= 23 &&
      minutoFinal >= 0 &&
      minutoFinal <= 59
    ) {
      const inicio =
        fechaBase.set({
          hour: horaFinal,
          minute: minutoFinal,
          second: 0,
          millisecond: 0
        });

      startTime =
        inicio.toISO();

      if (duracionMinutos > 0) {
        endTime =
          inicio
            .plus({
              minutes:
                duracionMinutos
            })
            .toISO();
      }

      if (
        fechaDetectadaEnMensaje ||
        horaDetectadaEnMensaje
      ) {
        origen =
          "mensaje_actual";
      } else {
        origen =
          "estado_guardado";
      }
    }
  }
}

const inicioFinal =
  startTime
    ? DateTime.fromISO(
        startTime,
        {
          zone: zonaHoraria
        }
      )
    : null;

// --------------------------------------------------
// Resultado
// --------------------------------------------------

return {
  json: {
    ...$json,

    estadoPeluqueria: {
