};

const DateTime =
  $now.constructor;

const config =
  $json.peluqueriaConfig || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const zonaHoraria =
  String(
    config.zona_horaria ||
    "America/Santiago"
  ).trim();

const diasABuscar =
  Math.max(
    Number(
      config.dias_a_buscar ||
      7
    ),
    1
  );

const duracionMinutos =
  Number(
    datosReserva.duracion_minutos ||
    resolucion.duracion_minutos ||
    estadoAnterior.duracion_minutos ||
    0
  );

const intervaloInicioMinutos =
  Number(
    datosReserva.intervalo_inicio_minutos ||
    resolucion.intervalo_inicio_minutos ||
    config.intervalo_inicio_minutos_default ||
    config.intervalo_inicio_minutos ||
    30
  );

const cantidadAlternativas =
  Math.max(
    Number(
      config.cantidad_alternativas ||
      config.max_alternativas ||
      3
    ),
    1
  );

const ahora =
  $now.setZone(
    zonaHoraria
  );

const inicioSolicitadoTexto =
  String(
    $json.startTime ||
    estadoAnterior.start_time ||
    ""
  ).trim();

const inicioSolicitado =
  inicioSolicitadoTexto
    ? DateTime.fromISO(
        inicioSolicitadoTexto,
        {
          zone: zonaHoraria
        }
      )
    : null;

const inicioBusqueda =
  ahora.startOf(
    "minute"
  );

const finBusqueda =
  ahora
    .startOf("day")
    .plus({
      days: diasABuscar
    });

return {
  json: {
    ...$json,

    busquedaAlternativasPeluqueria: {
      zona_horaria:
        zonaHoraria,

      dias_a_buscar:
        diasABuscar,

      cantidad_alternativas:
        cantidadAlternativas,

      duracion_minutos:
        duracionMinutos,

      intervalo_inicio_minutos:
        intervaloInicioMinutos,

      inicio_solicitado:
        inicioSolicitado?.isValid
          ? inicioSolicitado.toISO()
          : "",

      inicio_busqueda:
        inicioBusqueda.toISO(),

      fin_busqueda:
        finBusqueda.toISO()
    }
  }
};

const DateTime =
  $now.constructor;

const origen =
  $("Preparar búsqueda alternativas peluquería")
    .first()
    .json;

const busqueda =
  origen.busquedaAlternativasPeluqueria ||
  {};

const zonaHoraria =
  String(
    busqueda.zona_horaria ||
    "America/Santiago"
  ).trim();

const items =
  $input.all();

const esItemConError = (
  item
) => {
  const json =
    item?.json || {};

  return Boolean(
    json.error ||
    json.errorMessage ||
    json.executionError ||
    json.name === "NodeApiError" ||
    json.name === "NodeOperationError"
  );
};

const errorConsulta =
  items.some(
    esItemConError
  );

const convertirFecha = (
  valor
) => {
  const texto =
    String(valor || "").trim();

  if (!texto) {
    return "";
  }

  const esSoloFecha =
    /^\d{4}-\d{2}-\d{2}$/.test(
      texto
    );

  const fecha =
    esSoloFecha
      ? DateTime.fromISO(
          texto,
          {
            zone: zonaHoraria
          }
        ).startOf("day")
      : DateTime.fromISO(
          texto,
          {
            zone: zonaHoraria
          }
        );

  return fecha.isValid
    ? fecha.toISO()
    : "";
};

const eventosOcupados = [];

for (const item of items) {
  if (
    esItemConError(item)
  ) {
    continue;
  }

  const evento =
    item.json || {};

  if (
    evento.status === "cancelled"
  ) {
    continue;
  }

  const inicio =
    convertirFecha(
      evento.start?.dateTime ||
      evento.start?.date ||
      evento.startTime ||
      evento.start_time ||
      evento.inicio ||
      ""
    );

  const fin =
    convertirFecha(
      evento.end?.dateTime ||
      evento.end?.date ||
      evento.endTime ||
      evento.end_time ||
      evento.fin ||
      ""
    );

  if (
    inicio &&
    fin
  ) {
    eventosOcupados.push({
      inicio,
      fin
    });
  }
}

return [
  {
    json: {
      ...origen,

      consultaEventosPeluqueria: {
        es_valida:
          !errorConsulta,

        error_consulta:
          errorConsulta,

        total_eventos:
          eventosOcupados.length
      },

      eventosOcupadosPeluqueria:
        eventosOcupados
    }
  }
];

const DateTime =
  $now.constructor;

const config =
  $json.peluqueriaConfig || {};

const busqueda =
  $json.busquedaAlternativasPeluqueria ||
  {};

const eventos =
  Array.isArray(
    $json.eventosOcupadosPeluqueria
  )
    ? $json.eventosOcupadosPeluqueria
    : [];

const zonaHoraria =
  String(
    busqueda.zona_horaria ||
    config.zona_horaria ||
    "America/Santiago"
  ).trim();

const diasABuscar =
  Math.max(
    Number(
      busqueda.dias_a_buscar ||
      config.dias_a_buscar ||
      7
    ),
    1
  );

const cantidadAlternativas =
  Math.max(
    Number(
      busqueda.cantidad_alternativas ||
      config.cantidad_alternativas ||
      3
    ),
    1
  );

const duracionMinutos =
  Number(
    busqueda.duracion_minutos ||
    0
  );

const intervaloInicioMinutos =
  Math.max(
    Number(
      busqueda.intervalo_inicio_minutos ||
      config.intervalo_inicio_predeterminado_minutos ||
      config.intervalo_inicio_minutos_default ||
      config.intervalo_inicio_minutos ||
      30
    ),
    1
  );

const ahora =
  $now.setZone(
    zonaHoraria
  );

const inicioSolicitado =
  busqueda.inicio_solicitado
    ? DateTime.fromISO(
        busqueda.inicio_solicitado,
        {
          zone: zonaHoraria
        }
      )
    : null;

// --------------------------------------------------
// Horarios configurados
// --------------------------------------------------

const normalizarTexto = (
  valor
) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(
      /[\u0300-\u036f]/g,
      ""
    )
    .trim();

const nombresDias = {
  1: "lunes",
  2: "martes",
  3: "miercoles",
  4: "jueves",
  5: "viernes",
  6: "sabado",
  7: "domingo"
};

const horariosPorDia =
  config.horarios_por_dia ||
  config.horarios ||
  config.schedule ||
  {};

const buscarConfiguracionDia = (
  nombreDia
) => {
  if (
    !horariosPorDia ||
    typeof horariosPorDia !== "object"
  ) {
    return null;
  }

  for (
    const [clave, valor]
    of Object.entries(
      horariosPorDia
    )
  ) {
    if (
      normalizarTexto(clave) ===
      nombreDia
    ) {
      return valor;
    }
  }

  return null;
};

const normalizarVentanas = (
  valor
) => {
  if (
    valor === null ||
    valor === undefined ||
    valor === false
  ) {
    return [];
  }

  if (typeof valor === "string") {
    const coincidencia =
      valor.match(
        /(\d{1,2}:\d{2})\s*[-–]\s*(\d{1,2}:\d{2})/
      );

    return coincidencia
      ? [
          {
            apertura:
              coincidencia[1],

            cierre:
              coincidencia[2]
          }
        ]
      : [];
  }

  if (Array.isArray(valor)) {
    return valor.flatMap(
      (item) =>
        normalizarVentanas(item)
    );
  }

  if (typeof valor === "object") {
    const activo =
      valor.activo ??
      valor.active ??
      valor.habilitado ??
      true;

    if (activo === false) {
      return [];
    }

    const apertura =
      valor.apertura ||
      valor.inicio ||
      valor.desde ||
      valor.start ||
      valor.hora_inicio ||
      "";

    const cierre =
      valor.cierre ||
      valor.fin ||
      valor.hasta ||
      valor.end ||
      valor.hora_fin ||
      "";

    if (
      apertura &&
      cierre
    ) {
      return [
        {
          apertura:
            String(
              apertura
            ).trim(),

          cierre:
            String(
              cierre
            ).trim()
        }
      ];
    }

    return normalizarVentanas(
      valor.ventanas ||
      valor.bloques ||
      valor.rangos ||
      valor.windows ||
      []
    );
  }

  return [];
};

// --------------------------------------------------
// Utilidades
// --------------------------------------------------

const convertirHoraAMinutos = (
  valor
) => {
  const coincidencia =
    String(valor || "")
      .trim()
      .match(
        /^(\d{1,2}):(\d{2})$/
      );

  if (!coincidencia) {
    return null;
  }

  const horas =
    Number(coincidencia[1]);

  const minutos =
    Number(coincidencia[2]);

  if (
    horas < 0 ||
    horas > 23 ||
    minutos < 0 ||
    minutos > 59
  ) {
    return null;
  }

  return (
    horas * 60 +
    minutos
  );
};

const fechasBloqueadasConfiguradas =
  config.fechas_bloqueadas ||
  config.blocked_dates ||
  [];

const fechasBloqueadas =
  new Set(
    (
      Array.isArray(
        fechasBloqueadasConfiguradas
      )
        ? fechasBloqueadasConfiguradas
        : []
    )
      .map((item) => {
        if (
          typeof item === "string"
        ) {
          return item.trim();
        }

        return String(
          item?.fecha ||
          item?.date ||
          ""
        ).trim();
      })
      .filter(Boolean)
  );

const eventosNormalizados =
  eventos
    .map((evento) => {
      const inicio =
        DateTime.fromISO(
          evento.inicio,
          {
            zone: zonaHoraria
          }
        );

      const fin =
        DateTime.fromISO(
          evento.fin,
          {
            zone: zonaHoraria
          }
        );

      return {
        inicio,
        fin
      };
    })
    .filter(
      (evento) =>
        evento.inicio.isValid &&
        evento.fin.isValid
    );

const seSuperpone = (
  inicio,
  fin
) =>
  eventosNormalizados.some(
    (evento) =>
      inicio < evento.fin &&
      fin > evento.inicio
  );

// --------------------------------------------------
// Generar candidatos
// --------------------------------------------------

const candidatos = [];

const fechaInicial =
  ahora.startOf("day");

if (duracionMinutos > 0) {
  for (
    let desplazamiento = 0;
    desplazamiento < diasABuscar;
    desplazamiento++
  ) {
    const fecha =
      fechaInicial.plus({
        days: desplazamiento
      });

    const fechaIso =
      fecha.toISODate();

    if (
      fechasBloqueadas.has(
        fechaIso
      )
    ) {
      continue;
    }

    const nombreDia =
      nombresDias[fecha.weekday];

    const ventanas =
      normalizarVentanas(
        buscarConfiguracionDia(
          nombreDia
        )
      );

    for (
      const ventana
      of ventanas
    ) {
      const apertura =
        convertirHoraAMinutos(
          ventana.apertura
        );

      const cierre =
        convertirHoraAMinutos(
          ventana.cierre
        );

      if (
        apertura === null ||
        cierre === null ||
        cierre <= apertura
      ) {
        continue;
      }

      for (
        let minutoInicio =
          apertura;
        minutoInicio +
          duracionMinutos <=
          cierre;
        minutoInicio +=
          intervaloInicioMinutos
      ) {
        const hora =
          Math.floor(
            minutoInicio / 60
          );

        const minuto =
          minutoInicio % 60;

        const inicio =
          fecha.set({
            hour: hora,
            minute: minuto,
            second: 0,
            millisecond: 0
          });

        const fin =
          inicio.plus({
            minutes:
              duracionMinutos
          });

        if (
          inicio <= ahora
        ) {
          continue;
        }

        if (
          inicioSolicitado?.isValid &&
          inicio.toMillis() ===
            inicioSolicitado.toMillis()
        ) {
          continue;
        }

        if (
          seSuperpone(
            inicio,
            fin
          )
        ) {
          continue;
        }

        candidatos.push({
          inicio,
          fin
        });
      }
    }
  }
}

// --------------------------------------------------
// Ordenar por cercanía al horario solicitado
// --------------------------------------------------

const referencia =
  inicioSolicitado?.isValid
    ? inicioSolicitado
    : ahora;

candidatos.sort(
  (a, b) => {
    const distanciaA =
      Math.abs(
        a.inicio.toMillis() -
        referencia.toMillis()
      );

    const distanciaB =
      Math.abs(
        b.inicio.toMillis() -
        referencia.toMillis()
      );

    if (
      distanciaA !== distanciaB
    ) {
      return (
        distanciaA -
        distanciaB
      );
    }

    return (
      a.inicio.toMillis() -
      b.inicio.toMillis()
    );
  }
);

// --------------------------------------------------
// Formatear alternativas
// --------------------------------------------------

const opciones =
  candidatos
    .slice(
      0,
      cantidadAlternativas
    )
    .map(
      (candidato, indice) => ({
        numero:
          indice + 1,

        inicio:
          candidato.inicio.toISO(),

        fin:
          candidato.fin.toISO(),

        fecha:
          candidato.inicio.toISODate(),

        hora:
          candidato.inicio.toFormat(
            "HH:mm"
          ),

        texto:
          candidato.inicio
            .setLocale("es")
            .toFormat(
              "cccc d 'de' LLLL 'a las' HH:mm"
            )
      })
    );

return {
  json: {
    ...$json,

    alternativasPeluqueria: {
      hay_alternativas:
        opciones.length > 0,

      total:
        opciones.length,

      opciones
    }
  }
};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const alternativas =
  $json.alternativasPeluqueria || {};

const opciones =
  Array.isArray(
    alternativas.opciones
  )
    ? alternativas.opciones
    : [];

const hayAlternativas =
  alternativas.hay_alternativas === true &&
  opciones.length > 0;

const clinicId =
  String(
    $json.clinic_id ||
    estadoAnterior.clinic_id ||
    ""
  ).trim();

const sessionId =
  String(
    $json.session_id ||
    estadoAnterior.session_id ||
    ""
  ).trim();

const sessionKey =
  String(
    $json.session_key ||
    estadoAnterior.session_key ||
    (
      clinicId && sessionId
        ? `${clinicId}::${sessionId}`
        : ""
    )
  ).trim();

const serviceId =
  String(
    datosReserva.service_id ||
    resolucion.service_id ||
    estadoAnterior.service_id ||
    ""
  ).trim();

const nombreServicio =
  String(
    datosReserva.nombre_servicio ||
    resolucion.nombre_servicio ||
    estadoAnterior.nombre_servicio ||
    ""
  ).trim();

const duracionMinutos =
  Number(
    datosReserva.duracion_minutos ||
    resolucion.duracion_minutos ||
    estadoAnterior.duracion_minutos ||
    0
  );

const estadoPeluqueriaGuardar = {
  session_key:
    sessionKey,

  clinic_id:
    clinicId,

  session_id:
    sessionId,

  estado_peluqueria:
    hayAlternativas
      ? "esperando_seleccion_horario"
      : "sin_horarios_disponibles",

  service_id:
    serviceId,

  nombre_servicio:
    nombreServicio,

  duracion_minutos:
    duracionMinutos,

  nombre_tutor:
    String(
      datosReserva.nombre_tutor ||
      estadoAnterior.nombre_tutor ||
      ""
    ).trim(),

  telefono:
    String(
      datosReserva.telefono ||
      estadoAnterior.telefono ||
      ""
    ).trim(),

  nombre_mascota:
    String(
      datosReserva.nombre_mascota ||
      estadoAnterior.nombre_mascota ||
      ""
    ).trim(),

  especie:
    String(
      datosReserva.especie ||
      resolucion.especie ||
      estadoAnterior.especie ||
      "perro"
    ).trim(),

  tamano:
    String(
      datosReserva.tamano ||
      resolucion.tamano ||
      estadoAnterior.tamano ||
      ""
    ).trim(),

  tipo_pelaje:
    String(
      datosReserva.tipo_pelaje ||
      resolucion.tipo_pelaje ||
      estadoAnterior.tipo_pelaje ||
      ""
    ).trim(),

  fecha_pendiente:
    "",

  hora_pendiente:
    "",

  start_time:
    "",

  end_time:
    "",

  opciones_json:
    JSON.stringify(
      opciones
    ),

  updated_at:
    new Date().toISOString()
};

const textosOpciones =
  opciones.map(
    (opcion, indice) => {
      const numero =
        Number(
          opcion.numero ||
          indice + 1
        );

      const texto =
        String(
          opcion.texto || ""
        ).trim();

      return (
        `${numero}. ${texto}`
      );
    }
  );

let reply = "";

if (hayAlternativas) {
  const servicioTexto =
    nombreServicio
      ? ` para ${nombreServicio}`
      : "";

  reply =
    "El horario solicitado no está disponible. " +
    `Tengo estas alternativas reales${servicioTexto}:\n\n` +
    textosOpciones.join("\n") +
    "\n\nResponde con el número de la opción que prefieres.";
} else {
  reply =
    "No encontré horarios disponibles de peluquería dentro del período de búsqueda configurado. " +
    "Puedes indicar otra fecha o comunicarte directamente con la clínica.";
}

return {
  json: {
    ...$json,

    hayAlternativasPeluqueria:
      hayAlternativas,

    respuestaAlternativasPeluqueria:
      reply,

    estadoPeluqueriaGuardar
  }
};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const config =
  $json.peluqueriaConfig || {};

const clinicId =
  String(
    $json.clinic_id ||
    estadoAnterior.clinic_id ||
    ""
  ).trim();

const sessionId =
  String(
    $json.session_id ||
    estadoAnterior.session_id ||
    ""
  ).trim();

const sessionKey =
  String(
    $json.session_key ||
    estadoAnterior.session_key ||
    (
      clinicId && sessionId
        ? `${clinicId}::${sessionId}`
        : ""
    )
  ).trim();

const serviceId =
  String(
    datosReserva.service_id ||
    resolucion.service_id ||
    estadoAnterior.service_id ||
    ""
  ).trim();

const nombreServicio =
  String(
    datosReserva.nombre_servicio ||
    resolucion.nombre_servicio ||
    estadoAnterior.nombre_servicio ||
    ""
  ).trim();

const nombreTutor =
  String(
    datosReserva.nombre_tutor ||
    estadoAnterior.nombre_tutor ||
    ""
  ).trim();

const nombreMascota =
  String(
    datosReserva.nombre_mascota ||
    estadoAnterior.nombre_mascota ||
    ""
  ).trim();

const telefono =
  String(
    datosReserva.telefono ||
    estadoAnterior.telefono ||
    ""
  ).trim();

const especie =
  String(
    datosReserva.especie ||
    resolucion.especie ||
    estadoAnterior.especie ||
    "perro"
  ).trim();

const tamano =
  String(
    datosReserva.tamano ||
    resolucion.tamano ||
    estadoAnterior.tamano ||
    ""
  ).trim();

const tipoPelaje =
  String(
    datosReserva.tipo_pelaje ||
    resolucion.tipo_pelaje ||
    estadoAnterior.tipo_pelaje ||
    ""
  ).trim();

const duracionMinutos =
  Number(
    datosReserva.duracion_minutos ||
    resolucion.duracion_minutos ||
    estadoAnterior.duracion_minutos ||
    0
  );

const startTime =
  String(
    $json.startTime ||
    estadoAnterior.start_time ||
    ""
  ).trim();

const endTime =
  String(
    $json.endTime ||
    estadoAnterior.end_time ||
    ""
  ).trim();

const calendarId =
  String(
    config.calendar_id || ""
  ).trim();

const zonaHoraria =
  String(
    config.zona_horaria ||
    "America/Santiago"
  ).trim();

const datosConfirmacionValidos =
  Boolean(
    clinicId &&
    sessionId &&
    sessionKey &&
    serviceId &&
    nombreServicio &&
    nombreTutor &&
    nombreMascota &&
    telefono &&
    duracionMinutos > 0 &&
    startTime &&
    endTime &&
    calendarId
  );

const resumenEvento =
  `Peluquería - ${nombreMascota} - ${nombreServicio}`;

const descripcionEvento = [
  `Servicio: ${nombreServicio}`,
  `Mascota: ${nombreMascota}`,
  `Especie: ${especie}`,
  `Tamaño: ${tamano}`,
  tipoPelaje
    ? `Tipo de pelaje: ${tipoPelaje}`
    : "",
  `Tutor: ${nombreTutor}`,
  `Teléfono: ${telefono}`,
  `Duración: ${duracionMinutos} minutos`,
  `Clínica: ${clinicId}`,
  `Sesión: ${sessionId}`
]
  .filter(Boolean)
  .join("\n");

return {
  json: {
    ...$json,

    citaPeluqueria: {
      clinic_id:
        clinicId,

      session_id:
        sessionId,

      session_key:
        sessionKey,

      calendar_id:
        calendarId,

      zona_horaria:
        zonaHoraria,

      service_id:
        serviceId,

      nombre_servicio:
        nombreServicio,

      duracion_minutos:
        duracionMinutos,

      nombre_tutor:
        nombreTutor,

      nombre_mascota:
        nombreMascota,

      telefono,

      especie,

      tamano,

      tipo_pelaje:
        tipoPelaje,

      start_time:
        startTime,

      end_time:
        endTime,

      resumen_evento:
        resumenEvento,

      descripcion_evento:
        descripcionEvento,

      datos_confirmacion_validos:
        datosConfirmacionValidos
    }
  }
};

const solicitud =
  $("Preparar confirmación cita peluquería")
