    origen.citaPeluqueria || {};

  const zonaHoraria =
    String(
      cita.zona_horaria ||
      "America/Santiago"
    ).trim();

  const inicioTexto =
    String(
      cita.start_time || ""
    ).trim();

  const inicio =
    inicioTexto
      ? DateTime.fromISO(
          inicioTexto,
          {
            zone: zonaHoraria
          }
        )
      : null;

  const fechaTexto =
    inicio &&
    inicio.isValid
      ? inicio
          .setLocale("es")
          .toFormat(
            "cccc d 'de' LLLL 'a las' HH:mm"
          )
      : "";

  const servicio =
    String(
      cita.nombre_servicio ||
      "peluquería"
    ).trim();

  const mascota =
    String(
      cita.nombre_mascota ||
      "tu mascota"
    ).trim();

  const duracion =
    Number(
      cita.duracion_minutos || 0
    );

  let respuesta =
    `La cita de ${servicio} para ${mascota} quedó confirmada`;

  if (fechaTexto) {
    respuesta +=
      ` para el ${fechaTexto}`;
  }

  if (duracion > 0) {
    respuesta +=
      `. La duración estimada es de ${duracion} minutos.`;
  } else {
    respuesta += ".";
  }

  return respuesta;
})() }}

parameters.jsCode:
const entrada =
  $("Preparar clave estado urgencia").first().json;

const filaGuardada =
  $json || {};

const config =
  entrada.urgenciaConfig || {};

const zonaHoraria =
  config.zona_horaria ||
  "America/Santiago";

const ventanaContextoMinutos =
  Math.max(
    Number(
      config.ventana_contexto_minutos
    ) || 30,
    1
  );

const maxMensajesContexto =
  Math.max(
    Number(
      config.max_mensajes_contexto
    ) || 3,
    1
  );

const DateTime =
  $now.constructor;

const ahora =
  $now.setZone(zonaHoraria);

const ahoraIso =
  ahora.toISO();

const textoActual =
  String(
    entrada.message || ""
  ).trim();

// --------------------------------------------------
// Utilidades
// --------------------------------------------------

const convertirMensajes = (valor) => {
  if (Array.isArray(valor)) {
    return valor;
  }

  try {
    const resultado =
      JSON.parse(
        String(valor || "[]")
      );

    return Array.isArray(resultado)
      ? resultado
      : [];
  } catch (error) {
    return [];
  }
};

const normalizarMensajeGuardado = (item) => {
  if (typeof item === "string") {
    return {
      texto: item.trim(),
      at: ""
    };
  }

  if (
    item &&
    typeof item === "object"
  ) {
    return {
      texto: String(
        item.texto ||
        item.message ||
        ""
      ).trim(),

      at: String(
        item.at ||
        item.fecha ||
        ""
      ).trim()
    };
  }

  return {
    texto: "",
    at: ""
  };
};

// --------------------------------------------------
// Existencia y vencimiento del estado
// --------------------------------------------------

const existeEstadoUrgencia =
  Boolean(
    String(
      filaGuardada.state_key || ""
    ).trim()
  );

const expiraContextoGuardado =
  String(
    filaGuardada.expira_contexto_at ||
    ""
  ).trim();

let contextoUrgenciaExpirado =
  false;

if (existeEstadoUrgencia) {
  if (!expiraContextoGuardado) {
    contextoUrgenciaExpirado =
      true;
  } else {
    const fechaExpiracion =
      DateTime.fromISO(
        expiraContextoGuardado,
        {
          zone: zonaHoraria
        }
      );

    contextoUrgenciaExpirado =
      !fechaExpiracion.isValid ||
      fechaExpiracion <= ahora;
  }
}

// --------------------------------------------------
// Contexto reciente del usuario
// --------------------------------------------------

const mensajesPrevios =
  contextoUrgenciaExpirado
    ? []
    : convertirMensajes(
        filaGuardada
          .mensajes_recientes_json
      )
        .map(
          normalizarMensajeGuardado
        )
        .filter(
          (item) =>
            Boolean(item.texto)
        );

const mensajesConActual =
  textoActual
    ? [
        ...mensajesPrevios,
        {
          texto: textoActual,
          at: ahoraIso
        }
      ]
    : [...mensajesPrevios];

const mensajesContextoUrgencia =
  mensajesConActual.slice(
    -maxMensajesContexto
  );

const contextoUrgenciaTexto =
  mensajesContextoUrgencia
    .map(
      (item, indice) =>
        `Mensaje ${indice + 1}: ` +
        item.texto
    )
    .join("\n");

// --------------------------------------------------
// Episodio previo
// --------------------------------------------------

const estadoEpisodioPrevio =
  String(
    filaGuardada.estado_episodio ||
    "sin_episodio"
  )
    .trim()
    .toLowerCase();

const episodeIdPrevio =
  contextoUrgenciaExpirado
    ? ""
    : String(
        filaGuardada
          .episode_id_activo ||
        ""
      ).trim();

const episodioUrgenciaActivo =
  Boolean(episodeIdPrevio) &&
  [
    "activo_preventivo",
    "activo_inmediato"
  ].includes(
    estadoEpisodioPrevio
  );

const nuevoContextoUrgencia =
  !existeEstadoUrgencia ||
  contextoUrgenciaExpirado;

// --------------------------------------------------
// Estado consolidado
// --------------------------------------------------

const estadoUrgencia = {
  state_key:
    filaGuardada.state_key ||
    entrada.state_key_urgencia,

  clinic_id:
    filaGuardada.clinic_id ||
    entrada.clinic_id,

  session_id:
    filaGuardada.session_id ||
    entrada.session_id,

  canal_publico:
    entrada.channel ||
    filaGuardada.canal_publico ||
    config.canal_publico ||
    "streamlit",

  mensajes_recientes_json:
    JSON.stringify(
      mensajesContextoUrgencia
    ),

  ultimo_mensaje_usuario:
    textoActual,

  ultima_actividad_at:
    ahoraIso,

  episode_id_activo:
    episodeIdPrevio,

  alert_id_ultimo:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .alert_id_ultimo ||
          ""
        ),

  estado_episodio:
    contextoUrgenciaExpirado
      ? "sin_episodio"
      : estadoEpisodioPrevio,

  prioridad_actual:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .prioridad_actual ||
          ""
        ),

  categoria_actual:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .categoria_actual ||
          ""
        ),

  pregunta_seguridad_pendiente:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .pregunta_seguridad_pendiente ||
          ""
        ),

  pregunta_seguridad_at:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .pregunta_seguridad_at ||
          ""
        ),

  ultima_alerta_at:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .ultima_alerta_at ||
          ""
        ),

  ultima_notificacion_at:
    contextoUrgenciaExpirado
      ? ""
      : String(
          filaGuardada
            .ultima_notificacion_at ||
          ""
        ),

  expira_contexto_at:
    ahora
      .plus({
        minutes:
          ventanaContextoMinutos
      })
      .toISO(),

  created_at:
    filaGuardada.created_at ||
    ahoraIso,

  updated_at:
    ahoraIso
};

return {
  json: {
    ...entrada,

    existeEstadoUrgencia,
    nuevoContextoUrgencia,
    contextoUrgenciaExpirado,
    episodioUrgenciaActivo,

    mensajesContextoUrgencia,
    contextoUrgenciaTexto,

    estadoUrgencia
  }
};

const entrada = $json;

const mensajeActual =
  String(
    entrada.message || ""
  ).trim();

const contextoUrgenciaTexto =
  String(
    entrada.contextoUrgenciaTexto ||
    mensajeActual
  ).trim();

const estadoPrevio =
  entrada.estadoUrgencia || {};

// --------------------------------------------------
// Normalización
// --------------------------------------------------

const normalizar = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(
      /[\u0300-\u036f]/g,
      ""
    )
    .replace(
      /[^a-z0-9ñ\s]/g,
      " "
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

const mensajeNormalizado =
  normalizar(mensajeActual);

const contextoNormalizado =
  normalizar(
    contextoUrgenciaTexto
  );

const textoEvaluacion =
  contextoNormalizado ||
  mensajeNormalizado;

// --------------------------------------------------
// Estado previo del episodio
// --------------------------------------------------

const estadoEpisodioPrevio =
  String(
    estadoPrevio.estado_episodio ||
    ""
  ).trim();

const prioridadPrevia =
  String(
    estadoPrevio.prioridad_actual ||
    ""
  ).trim();

const categoriaPrevia =
  String(
    estadoPrevio.categoria_actual ||
    ""
  ).trim();

const episodioActivoPrevio =
  Boolean(
    entrada.episodioUrgenciaActivo
  ) ||
  [
    "activo_preventivo",
    "activo_inmediato"
  ].includes(
    estadoEpisodioPrevio
  );

// --------------------------------------------------
// Utilidades
// --------------------------------------------------

const coincideAlguna = (
  texto,
  patrones
) =>
  patrones.some(
    (patron) =>
      patron.test(texto)
  );

const reglasActivadas = [];
const evidencias = [];

const registrar = (
  regla,
  evidencia
) => {
  if (
    !reglasActivadas.includes(
      regla
    )
  ) {
    reglasActivadas.push(
      regla
    );
  }

  if (
    evidencia &&
    !evidencias.includes(
      evidencia
    )
  ) {
    evidencias.push(
      evidencia
    );
  }
};

// --------------------------------------------------
// Contextos que no deben abrir una alerta nueva
// --------------------------------------------------

const patronesAtencionReportada = [
  /\bya vamos camino\b/,
  /\bya estamos camino\b/,
  /\bvamos a la clinica\b/,
  /\bestamos yendo a la clinica\b/,
  /\bya esta en la clinica\b/,
  /\bya estamos en la clinica\b/,
  /\bya lo atendieron\b/,
  /\bya la atendieron\b/,
  /\bya fue atendid[oa]\b/,
  /\bya lo esta viendo el veterinario\b/,
  /\bya la esta viendo el veterinario\b/,
  /\bestamos con el veterinario\b/,
  /\bya lo llevamos al veterinario\b/,
  /\bya la llevamos al veterinario\b/,
  /\bya recibio atencion veterinaria\b/,
  /\bya ha recibido atencion veterinaria\b/,
  /\brecibio atencion veterinaria y esta estable\b/,
  /\bya fue atendid[oa] por (?:el|la|un|una) veterinari[oa]\b/,
  /\bya (?:lo|la) atendio (?:el|la|un|una) veterinari[oa]\b/,
  /\bya (?:lo|la) vio (?:el|la|un|una) veterinari[oa]\b/
];

const patronesNegacionAtencionReportada = [
  /\bno recibio atencion veterinaria\b/,
  /\bno ha recibido atencion veterinaria\b/,
  /\btodavia no recibio atencion veterinaria\b/,
  /\btodavia no ha recibido atencion veterinaria\b/,
  /\baun no recibio atencion veterinaria\b/,
  /\baun no ha recibido atencion veterinaria\b/,
  /\bno fue atendid[oa]\b/,
  /\btodavia no fue atendid[oa]\b/,
  /\baun no fue atendid[oa]\b/
];

const parecePreguntaAtencionReportada =
  mensajeActual.includes("?");

const mencionaAtencionReportada =
  coincideAlguna(
    mensajeNormalizado,
    patronesAtencionReportada
  ) &&
  !coincideAlguna(
    mensajeNormalizado,
    patronesNegacionAtencionReportada
  ) &&
  !parecePreguntaAtencionReportada;

const patronesInformativos = [
  /\bque pasa si\b/,
  /\bque hago si\b/,
  /\bque debo hacer si\b/,
  /\bque hacer si\b/,
  /\bque hacer ante\b/,
  /\bque hago ante\b/,
  /\bcomo actuar si\b/,
  /\bcomo saber si\b/,
  /\bcuales son los sintomas\b/,
  /\bque sintomas produce\b/,
  /\bes peligroso que\b/,
  /\bpuede ser peligroso\b/,
  /\bsolo quiero saber\b/,
  /\bquiero saber sobre\b/,
  /\binformacion sobre\b/,
  /\bes una pregunta general\b/,
  /\bque hacer en caso de\b/
];

const esPreguntaInformativa =
  coincideAlguna(
    mensajeNormalizado,
    patronesInformativos
  );

const patronesHipoteticos = [
  /\bhipoteticamente\b/,
  /\bsupongamos que\b/,
  /\ben caso de que\b/,
  /\bsi algun dia\b/,
  /\bsi llegara a\b/,
  /\bsi mi perro llegara\b/,
  /\bsi mi gato llegara\b/
];

const esSituacionHipotetica =
  coincideAlguna(
    mensajeNormalizado,
    patronesHipoteticos
  );

// --------------------------------------------------
// Contexto histórico conservador
// --------------------------------------------------

const patronesMarcaHistorica = [
  /\bhace (?:un|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|\d+) (?:dia|dias|semana|semanas|mes|meses|ano|anos)\b/,
  /\besto paso hace\b/,
  /\bocurrio hace\b/,
  /\bfue hace varios dias\b/,
  /\bfue hace varias semanas\b/,
  /\bfue hace varios meses\b/,
  /\bfue hace varios anos\b/,
  /\bfue la semana pasada\b/,
  /\bfue el mes pasado\b/,
  /\bfue el ano pasado\b/,
  /\bcuando era cachorro\b/,
  /\bcuando era cachorra\b/,
  /\bcuando era pequeno\b/,
  /\bcuando era pequena\b/,
  /\bocurrio hace meses\b/,
  /\bocurrio hace anos\b/,
  /\bpaso hace meses\b/,
  /\bpaso hace anos\b/,
  /\bsucedio hace meses\b/,
  /\bsucedio hace anos\b/
];

const patronesBienestarActual = [
  /\bactualmente esta bien\b/,
  /\bactualmente se encuentra bien\b/,
  /\bahora esta bien\b/,
  /\bahora esta completamente bien\b/,
  /\bahora se encuentra bien\b/,
  /\bahora se encuentra completamente bien\b/,
  /\bhoy esta bien\b/,
  /\bhoy se encuentra bien\b/,
  /\ben este momento esta bien\b/,
  /\bya esta bien\b/,
  /\besta completamente bien\b/,
  /\bse encuentra completamente bien\b/,
  /\bactualmente esta normal\b/,
  /\bahora esta normal\b/,
  /\bno tiene sintomas actualmente\b/,
  /\bactualmente no tiene sintomas\b/,
  /\bno tiene sintomas ahora\b/,
  /\bahora no tiene sintomas\b/,
  /\bdesde entonces esta bien\b/,
  /\bdesde ese momento esta bien\b/,
  /\bya se recupero\b/,
  /\bse recupero por completo\b/,
  /\bya paso completamente\b/
];

const patronesHistoricosCerradosDirectos = [
  /\bya paso completamente\b/,
  /\beso ya paso\b/,
  /\bese episodio ya paso\b/,
  /\bya se recupero por completo\b/,
  /\bse recupero completamente\b/,
  /\bfue un episodio antiguo y ahora esta bien\b/,
  /\bfue hace tiempo y ahora esta bien\b/
];

// Una señal se considera ACTUAL si:
//
// 1. La marca temporal actual aparece antes de la señal:
//    "ahora no puede respirar"
//
// 2. La señal aparece inmediatamente seguida por una marca temporal:
//    "no puede respirar ahora"
//
// Esto evita interpretar incorrectamente:
// "se electrocutó hace un mes, pero ahora está bien"
// como una electrocución actual.

const patronesSenalUrgenteActual = [
  /\b(?:ahora(?: mismo)?|actualmente|hoy|en este momento)\b.{0,120}\b(?:no puede respirar|no logra respirar|asfixia|se esta asfixiando|se esta desmayando|esta convulsionando|esta inconsciente|no responde|sangra mucho|no para de sangrar|no puede orinar|vomita sangre|descarga electrica|se electrocuto|hueso expuesto|fractura abierta)\b/,

  /\b(?:no puede respirar|no logra respirar|asfixia|se esta asfixiando|se esta desmayando|esta convulsionando|esta inconsciente|no responde|sangra mucho|no para de sangrar|no puede orinar|vomita sangre|descarga electrica|se electrocuto|hueso expuesto|fractura abierta)\b\s+(?:ahora(?: mismo)?|actualmente|hoy|en este momento)\b/
];

const tieneMarcaHistorica =
  coincideAlguna(
    mensajeNormalizado,
    patronesMarcaHistorica
  );

const confirmaBienestarActual =
  coincideAlguna(
    mensajeNormalizado,
    patronesBienestarActual
  );

const esHistoricoCerradoDirecto =
  coincideAlguna(
    mensajeNormalizado,
    patronesHistoricosCerradosDirectos
  );

const haySenalUrgenteActual =
  coincideAlguna(
    mensajeNormalizado,
    patronesSenalUrgenteActual
  );

const esCasoHistorico =
  Boolean(
    (
      (
        tieneMarcaHistorica &&
        confirmaBienestarActual
      ) ||
      esHistoricoCerradoDirecto
    ) &&
    !haySenalUrgenteActual
  );

// --------------------------------------------------
// Negaciones por señal
// --------------------------------------------------

const patronesNegacionExplicita = [
  // Señales originales
  /\bno esta convulsionando\b/,
  /\bno tiene convulsiones\b/,
  /\bno se desmayo\b/,
  /\bno esta inconsciente\b/,
  /\bno tiene dificultad para respirar\b/,
  /\bno le cuesta respirar\b/,
  /\bno le cuesta mucho respirar\b/,
  /\bno esta sangrando\b/,
  /\bno sangra\b/,
  /\bno comio nada\b/,
  /\bno trago nada\b/,
  /\bno ingirio nada\b/,
  /\bno tiene sintomas\b/,
  /\besta completamente bien\b/,

  // Nuevas señales LAB-024.1
  /\bno tiene asfixia\b/,
  /\bno esta con asfixia\b/,
  /\bno se esta asfixiando\b/,
  /\bno se asfixia\b/,
  /\bno se electrocuto\b/,
  /\bno recibio descarga electrica\b/,
  /\bno recibio una descarga electrica\b/,
  /\bno tuvo descarga electrica\b/,
  /\bno tuvo una descarga electrica\b/,
  /\bno se atoro\b/,
  /\bno esta atorad[oa]\b/,
  /\bno se atraganto\b/,
  /\bno esta atragantad[oa]\b/,
  /\bno tiene nada atorado\b/,
  /\bno tiene un objeto atorado\b/,
  /\bno tiene hueso expuesto\b/,
  /\bno tiene fractura abierta\b/,
  /\bno tiene una fractura abierta\b/,
  /\bno tiene fractura\b/,
  /\bno tiene una fractura\b/,
  /\bno lo mordio una serpiente\b/,
  /\bno la mordio una serpiente\b/,
  /\bno fue mordid[oa] por una serpiente\b/,
  /\bno cayo al agua\b/,
  /\bno se cayo al agua\b/,
  /\bno trago mucha agua\b/,
  /\bno esta desorientad[oa]\b/,
  /\bno tiene encias palidas\b/,
  /\bno tiene encias azules\b/,
  /\bno tiene la lengua azul\b/,
  /\bno (?:comio|trago|ingirio) (?:un|una) (?:juguete|calcetin|moneda|pila|bateria|aguja|anzuelo)\b/
];

const neutralizarPatrones = (
  texto,
  patrones
) => {
  let resultado =
    String(texto || "");

  for (const patron of patrones) {
    const flags =
      patron.flags.includes("g")
        ? patron.flags
        : `${patron.flags}g`;

    resultado = resultado.replace(
      new RegExp(
        patron.source,
        flags
      ),
      " "
    );
  }

  return resultado
    .replace(
      /\s+/g,
      " "
    )
    .trim();
};

const hayNegacionExplicita =
  coincideAlguna(
    mensajeNormalizado,
    patronesNegacionExplicita
  );

const mensajeEvaluable =
  neutralizarPatrones(
    mensajeNormalizado,
    patronesNegacionExplicita
  );

const contextoEvaluable =
  neutralizarPatrones(
    textoEvaluacion,
    patronesNegacionExplicita
  );

const textoEvaluacionFiltrado =
  contextoEvaluable ||
  mensajeEvaluable;

// --------------------------------------------------
// Resultado base
// --------------------------------------------------

let prioridadDeterminista =
  "sin_prioridad";

let categoriaDeterminista =
  "";

let tipoContextoUrgencia =
  "caso_actual";

let requiereClasificacionIA =
  false;

let motivo =
  "No se detectaron señales prioritarias.";

// --------------------------------------------------
// Atención ya reportada
// --------------------------------------------------

if (mencionaAtencionReportada) {
  tipoContextoUrgencia =
    "atencion_reportada";

  motivo =
    "El usuario informó que la mascota ya está recibiendo o buscando atención veterinaria.";
}

// --------------------------------------------------
// Exclusiones contextuales
// --------------------------------------------------

else if (
  !episodioActivoPrevio &&
  esPreguntaInformativa
) {
  tipoContextoUrgencia =
    "pregunta_informativa";

  motivo =
    "El mensaje corresponde a una consulta informativa general.";
}

else if (
  !episodioActivoPrevio &&
  esSituacionHipotetica
) {
  tipoContextoUrgencia =
    "situacion_hipotetica";

  motivo =
    "El mensaje describe una situación hipotética.";
}

else if (
  !episodioActivoPrevio &&
  esCasoHistorico
) {
  tipoContextoUrgencia =
    "caso_historico";

  motivo =
    "El mensaje describe un hecho pasado y confirma que actualmente no existe una señal prioritaria.";
}

else {
  // ------------------------------------------------
  // Prioridad inmediata
  // ------------------------------------------------

  const reglasInmediatas = [
    {
      categoria:
        "respiratoria",

      regla:
        "respiratoria_no_puede_respirar",

