        /\btiene convulsiones\b/,
        /\bataque convulsivo\b/,
        /\bcrisis convulsiva\b/
      ]
    },

    {
      categoria:
        "alteracion_conciencia",

      regla:
        "conciencia_desmayo_no_responde",

      evidencia:
        "Desmayo o alteración de conciencia",

      patrones: [
        /\bse esta desmayando\b/,
        /\bse desmayo\b/,
        /\besta inconsciente\b/,
        /\bno responde\b/,
        /\bperdio el conocimiento\b/,
        /\besta sin reaccionar\b/
      ]
    },

    {
      categoria:
        "trauma",

      regla:
        "trauma_mayor",

      evidencia:
        "Trauma importante informado",

      patrones: [
        /\blo atropellaron\b/,
        /\bla atropellaron\b/,
        /\bfue atropellad[oa]\b/,
        /\bmi (perro|perra|gato|gata|mascota|animal) fue atropellad[oa]\b/,
        /\batropellaron a mi (perro|perra|gato|gata|mascota|animal)\b/,
        /\batropellaron al (perro|gato|animal)\b/,
        /\batropellaron a la (perra|gata|mascota)\b/,
        /\b(un|el) (auto|vehiculo|camion|camioneta|moto) atropello a mi (perro|perra|gato|gata|mascota|animal)\b/,
        /\bmi (perro|perra|gato|gata|mascota|animal) fue golpead[oa] por (un|el) (auto|vehiculo|camion|camioneta|moto)\b/,
        /\bcayo de una altura\b/,
        /\bcayo desde un segundo piso\b/,
        /\bgolpe muy fuerte\b/,
