        "ocular_grave",

      regla:
        "ocular_trauma_grave",

      evidencia:
        "Lesión ocular grave informada",

      patrones: [
        /\bse le salio el ojo\b/,
        /\bojo fuera de lugar\b/,
        /\bherida profunda en el ojo\b/,
        /\btrauma grave en el ojo\b/
      ]
    }
