  for (
    const regla of reglasInmediatas
  ) {
    if (
      coincideAlguna(
        textoEvaluacionFiltrado,
        regla.patrones
      )
    ) {
      prioridadDeterminista =
        "prioridad_inmediata";

      categoriaDeterminista =
        regla.categoria;

