    }
  }

  // ------------------------------------------------
  // Prioridad preventiva: ingestión desconocida
  // ------------------------------------------------

  if (
    prioridadDeterminista ===
    "sin_prioridad"
  ) {
    const patronesIngestionDesconocida = [
      /\bcomio algo del suelo\b/,
      /\bse comio algo del suelo\b/,
      /\bcomio algo en el suelo\b/,
      /\btrago algo del suelo\b/,
      /\bingirio algo del suelo\b/,
      /\blamio algo del suelo\b/,
