      )
    ) {
      prioridadDeterminista =
        "prioridad_preventiva";

      categoriaDeterminista =
        "posible_intoxicacion";

      registrar(
        "posible_ingestion_desconocida",
        "Posible ingestión de una sustancia u objeto desconocido"
      );
    }
  }

  // ------------------------------------------------
  // Otras reglas preventivas existentes
  // ------------------------------------------------

  if (
    prioridadDeterminista ===
    "sin_prioridad"
  ) {
    const reglasPreventivas = [
      {
        categoria:
          "respiratoria",

        regla:
          "respiratoria_ambigua",

        evidencia:
          "Cambio respiratorio que requiere evaluación",

        patrones: [
          /\brespira raro\b/,
          /\brespira muy rapido\b/,
          /\bjadea demasiado\b/,
          /\btose de forma repentina\b/
        ]
      },

      {
        categoria:
          "deterioro_subito",

        regla:
          "deterioro_rapido",

        evidencia:
