          "Debilidad o caídas repetidas",

        patrones: [
          /\bse cae al caminar\b/,
          /\bno puede mantenerse en pie\b/,
          /\besta muy debil\b/
        ]
      }
    ];

    for (
      const regla of reglasPreventivas
    ) {
      if (
        coincideAlguna(
          textoEvaluacionFiltrado,
          regla.patrones
        )
      ) {
        prioridadDeterminista =
          "prioridad_preventiva";

        categoriaDeterminista =
          regla.categoria;

        registrar(
          regla.regla,
          regla.evidencia
        );

        break;
      }
    }
  }

  // ------------------------------------------------
  // Mantener bloqueo si ya existe episodio activo
  // ------------------------------------------------

  if (
    prioridadDeterminista ===
      "sin_prioridad" &&
    episodioActivoPrevio
  ) {
    prioridadDeterminista =
      [
        "prioridad_inmediata",
        "prioridad_preventiva"
      ].includes(prioridadPrevia)
        ? prioridadPrevia
        : "prioridad_preventiva";

    categoriaDeterminista =
      categoriaPrevia ||
      "otra_senal_prioritaria";

    registrar(
      "episodio_urgencia_previo_activo",
      "La sesión mantiene un episodio urgente activo"
    );
  }

  // ------------------------------------------------
  // Gate clínico ampliado para IA controlada
  // ------------------------------------------------

  if (
    prioridadDeterminista ===
      "sin_prioridad"
  ) {
    const patronesContextoClinicoNoResuelto = [
      // Ambigüedad original
      /\besta muy raro\b/,
