      /\bse asfixia\b/,

      // Electrocución
      /\belectrocucion\b/,
      /\bse electrocuto\b/,
      /\bdescarga electrica\b/,
      /\brecibio una descarga electrica\b/,

      // Obstrucción / atragantamiento
      /\bse atoro\b/,
      /\besta atorad[oa]\b/,
      /\bse atraganto\b/,
      /\besta atragantad[oa]\b/,
      /\balgo atorado\b/,
      /\bobjeto atorado\b/,
      /\bno puede tragar\b/,
      /\bno logra tragar\b/,

      // Trauma
      /\bhueso expuesto\b/,
      /\bfractura abierta\b/,
      /\bfractura\b/,
      /\bse quebro\b/,
      /\bherida profunda\b/,
      /\bcorte profundo\b/,
      /\bherida abierta\b/,
      /\bno puede caminar\b/,
      /\bno puede pararse\b/,

      // Mordeduras peligrosas
      /\bmordedura de serpiente\b/,
      /\blo mordio una serpiente\b/,
      /\bla mordio una serpiente\b/,
      /\bmordedura de arana\b/,
      /\blo mordio una arana\b/,
      /\bla mordio una arana\b/,

      // Accidentes con agua
      /\bcayo al agua\b/,
      /\bse cayo al agua\b/,
      /\btrago mucha agua\b/,
      /\bcasi se ahoga\b/,

      // Signos preocupantes
      /\bencias palidas\b/,
      /\bencias azules\b/,
      /\blengua azul\b/,
      /\besta desorientad[oa]\b/,

      // Cuerpos extraños
      /\b(?:comio|trago|ingirio) (?:un|una) (?:juguete|calcetin|moneda|pila|bateria|aguja|anzuelo)\b/
    ];

    if (
      coincideAlguna(
        mensajeEvaluable,
        patronesContextoClinicoNoResuelto
      )
    ) {
      requiereClasificacionIA =
        true;

      categoriaDeterminista =
        "otra_senal_prioritaria";

      registrar(
        "contexto_clinico_no_resuelto_requiere_ia",
        "El mensaje describe una situación clínica o accidental potencialmente prioritaria que requiere clasificación controlada"
      );

      motivo =
        "El mensaje describe una situación potencialmente prioritaria no resuelta por las reglas deterministas.";
    }
  }

  // ------------------------------------------------
  // Caso negado solo si no queda señal positiva
  // ------------------------------------------------

  if (
    prioridadDeterminista ===
      "sin_prioridad" &&
    !requiereClasificacionIA &&
    hayNegacionExplicita &&
    !episodioActivoPrevio
  ) {
    tipoContextoUrgencia =
      "caso_negado";

    motivo =
      "El usuario negó explícitamente una o más señales y no quedaron otras señales prioritarias activas.";
  }

  if (
    prioridadDeterminista ===
    "prioridad_inmediata"
  ) {
    motivo =
      "Se detectó al menos una señal determinista de prioridad inmediata.";
  }

  if (
    prioridadDeterminista ===
    "prioridad_preventiva"
  ) {
    motivo =
      "Se detectó al menos una señal determinista de prioridad preventiva.";
  }
}

// --------------------------------------------------
// Salida
// --------------------------------------------------

const evaluacionDeterministaUrgencia = {
