return {
  json: {
    ...entrada,

    prioridadDeterminista,
    categoriaDeterminista,
    tipoContextoUrgencia,
    requiereClasificacionIA,

    reglasUrgenciaActivadas:
      reglasActivadas,

    evidenciasUrgencia:
      evidencias,

    mencionaAtencionReportada,

    evaluacionDeterministaUrgencia
  }
};

const entradaOriginal =
  $("Preparar clasificación IA urgencia")
    .first()
    .json;

const respuestaModelo =
  $json.output ??
  $json.text ??
  $json.response ??
  $json.content ??
  "";

const prioridadesPermitidas = [
  "prioridad_inmediata",
  "prioridad_preventiva",
  "sin_prioridad"
];

const categoriasPermitidas = [
  "respiratoria",
  "neurologica",
  "alteracion_conciencia",
  "trauma",
  "hemorragia",
  "posible_intoxicacion",
  "urinaria",
  "termica",
  "gastrointestinal_grave",
  "reproductiva",
  "ocular_grave",
  "dolor_deterioro",
  "deterioro_subito",
  "otra_senal_prioritaria",
  "sin_categoria"
];

const contextosPermitidos = [
  "caso_actual",
  "caso_negado",
  "caso_historico",
  "pregunta_informativa",
  "situacion_hipotetica",
  "contexto_insuficiente"
];

const confianzasPermitidas = [
  "alta",
  "media",
  "baja"
];

const preguntasPermitidas = [
  "",
  "¿Está consciente?",
  "¿Está respirando con normalidad?",
  "¿El sangrado continúa?",
  "¿Está convulsionando ahora?",
  "¿Logra orinar?",
  "¿Sabes qué sustancia pudo ingerir?",
  "¿Está empeorando rápidamente?",
  "¿En qué comuna o sector te encuentras?"
];

const limpiarTextoJson = (valor) => {
  if (
    valor &&
    typeof valor === "object"
  ) {
    return valor;
  }

  return String(valor || "")
    .trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
};

const extraerObjetoJson = (valor) => {
  const limpio =
    limpiarTextoJson(valor);

  if (
    limpio &&
    typeof limpio === "object"
  ) {
    return limpio;
  }

  try {
    return JSON.parse(limpio);
  } catch (errorDirecto) {
    const inicio =
      limpio.indexOf("{");

    const fin =
      limpio.lastIndexOf("}");

    if (
      inicio >= 0 &&
      fin > inicio
    ) {
      try {
        return JSON.parse(
          limpio.slice(
            inicio,
            fin + 1
          )
        );
      } catch (errorRecorte) {
        return null;
      }
    }

    return null;
  }
};

const normalizarCadena = (valor) =>
  String(valor || "")
    .trim()
    .toLowerCase();

const objetoIA =
  extraerObjetoJson(
    respuestaModelo
  );

let clasificacionIAValida =
  Boolean(
    objetoIA &&
    typeof objetoIA === "object" &&
    !Array.isArray(objetoIA)
  );

let prioridadIA =
  normalizarCadena(
    objetoIA?.prioridad
  );

let categoriaIA =
  normalizarCadena(
    objetoIA?.categoria
  );

let tipoContextoIA =
  normalizarCadena(
    objetoIA?.tipo_contexto
  );

let confianzaIA =
  normalizarCadena(
    objetoIA?.confianza
  );

let evidenciasIA =
  Array.isArray(
    objetoIA?.evidencias
  )
    ? objetoIA.evidencias
        .map(
          (item) =>
            String(item || "")
              .trim()
        )
        .filter(Boolean)
        .slice(0, 5)
    : [];

let preguntaSeguridadIA =
  String(
    objetoIA?.pregunta_seguridad ||
    ""
  ).trim();

const erroresValidacion = [];

if (
  !prioridadesPermitidas.includes(
    prioridadIA
  )
) {
  clasificacionIAValida =
    false;

  erroresValidacion.push(
    "prioridad_invalida"
  );
}

if (
  !categoriasPermitidas.includes(
    categoriaIA
  )
) {
  clasificacionIAValida =
    false;

  erroresValidacion.push(
    "categoria_invalida"
  );
}

if (
  !contextosPermitidos.includes(
    tipoContextoIA
  )
) {
  clasificacionIAValida =
    false;

  erroresValidacion.push(
    "tipo_contexto_invalido"
  );
}

if (
  !confianzasPermitidas.includes(
    confianzaIA
  )
) {
  clasificacionIAValida =
    false;

  erroresValidacion.push(
    "confianza_invalida"
  );
}

if (
  !preguntasPermitidas.includes(
    preguntaSeguridadIA
  )
) {
  preguntaSeguridadIA = "";
  erroresValidacion.push(
    "pregunta_seguridad_no_permitida"
  );
}

// --------------------------------------------------
// Fallback conservador
// --------------------------------------------------

let usoFallbackIA =
  false;

let motivoFallbackIA =
  "";

if (!clasificacionIAValida) {
  usoFallbackIA =
    true;

  prioridadIA =
    "prioridad_preventiva";

  categoriaIA =
    entradaOriginal
      .categoriaDeterminista ||
    "otra_senal_prioritaria";

  tipoContextoIA =
    "contexto_insuficiente";

  confianzaIA =
    "baja";

  evidenciasIA =
    Array.isArray(
      entradaOriginal
        .evidenciasUrgencia
    )
      ? entradaOriginal
          .evidenciasUrgencia
      : [];

  preguntaSeguridadIA =
    "";

  motivoFallbackIA =
    "La salida de IA fue inválida o incompleta.";
}

// --------------------------------------------------
// La IA no libera un caso ambiguo sin alta confianza
// --------------------------------------------------

const contextoPermiteSinPrioridad = [
  "caso_negado",
  "caso_historico",
  "pregunta_informativa",
  "situacion_hipotetica"
].includes(tipoContextoIA);

if (
  prioridadIA ===
    "sin_prioridad" &&
  (
    confianzaIA !== "alta" ||
    !contextoPermiteSinPrioridad
  )
) {
  usoFallbackIA =
    true;

  prioridadIA =
    "prioridad_preventiva";

  categoriaIA =
    categoriaIA ===
      "sin_categoria"
      ? (
          entradaOriginal
            .categoriaDeterminista ||
          "otra_senal_prioritaria"
        )
      : categoriaIA;

  tipoContextoIA =
    "contexto_insuficiente";

  motivoFallbackIA =
    "La IA no entregó confianza suficiente para liberar el flujo comercial.";
}

// --------------------------------------------------
// Categoría obligatoria cuando existe prioridad
// --------------------------------------------------

if (
  prioridadIA !==
    "sin_prioridad" &&
  categoriaIA ===
    "sin_categoria"
) {
  categoriaIA =
    entradaOriginal
      .categoriaDeterminista ||
    "otra_senal_prioritaria";
}

// --------------------------------------------------
// Resultado normalizado
// --------------------------------------------------

const evaluacionIAUrgencia = {
  prioridad:
    prioridadIA,

  categoria:
    categoriaIA,

  tipo_contexto:
    tipoContextoIA,

  confianza:
    confianzaIA,

