  }
};

const entradaOriginal =
  $("Preparar clasificación IA urgencia")
    .first()
    .json;

// --------------------------------------------------
// Sanitización de errores técnicos
// --------------------------------------------------

const normalizarError = (valor) => {
  const texto = String(
    valor ||
    "error_clasificacion_ia_sin_detalle_tecnico"
  )
    .replace(
      /https?:\/\/\S+/gi,
      "[URL_REDACTADA]"
    )
    .replace(
      /\bBearer\s+\S+/gi,
      "[TOKEN_REDACTADO]"
    )
    .replace(
      /\b[a-z0-9_\-]{32,}\b/gi,
      "[VALOR_REDACTADO]"
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

  return texto.slice(0, 300);
};

const convertirTextoSeguro = (valor) => {
  if (
    typeof valor === "string"
  ) {
    return valor.trim();
  }

  if (
    valor &&
    typeof valor === "object"
  ) {
    try {
      return JSON.stringify(
        valor
      );
    } catch {
      return "";
    }
  }

  return "";
};

// Solo se consideran campos explícitamente técnicos.
// Nunca se usa $json.message, porque puede contener
// el mensaje original del usuario.

const candidatosError = [
  $json.error?.message,
  $json.error?.description,
  $json.error?.cause?.message,

  $json.error?.response?.data?.error?.message,
  $json.error?.response?.data?.message,

  $json.response?.data?.error?.message,
  $json.response?.data?.message,

  $json.executionError?.message,
  $json.nodeExecutionError?.message,

  $json.cause?.message,
  $json.details?.message,

  $json.errorMessage,
  $json.statusMessage,

  typeof $json.error === "string"
    ? $json.error
    : ""
];

const errorTecnicoEncontrado =
  candidatosError
    .map(
      convertirTextoSeguro
    )
    .find(Boolean) ||
  "error_clasificacion_ia_sin_detalle_tecnico";

const errorClasificacionIASanitizado =
  normalizarError(
    errorTecnicoEncontrado
  );

// --------------------------------------------------
// Resultado conservador
// --------------------------------------------------

const categoriaFallback =
  String(
    entradaOriginal
      .categoriaDeterminista ||
    "otra_senal_prioritaria"
  ).trim();

const evidenciasFallback =
  Array.isArray(
    entradaOriginal
      .evidenciasUrgencia
  )
    ? entradaOriginal
        .evidenciasUrgencia
        .map(
          (item) =>
            String(
              item || ""
            ).trim()
        )
        .filter(Boolean)
        .slice(0, 5)
    : [];

const evaluacionIAUrgencia = {
  prioridad:
    "prioridad_preventiva",

  categoria:
    categoriaFallback,

  tipo_contexto:
    "contexto_insuficiente",

  confianza:
    "baja",

  evidencias:
    evidenciasFallback,

  pregunta_seguridad:
    "",

  salida_valida:
    false,

  uso_fallback:
    true,

  motivo_fallback:
    "La clasificación mediante IA falló técnicamente.",

  errores_validacion: [
    "error_tecnico_modelo"
  ]
};

return {
  json: {
    ...entradaOriginal,

    prioridadIA:
      "prioridad_preventiva",

    categoriaIA:
      categoriaFallback,

    tipoContextoIA:
      "contexto_insuficiente",

    confianzaIA:
      "baja",

    evidenciasIA:
      evidenciasFallback,

    preguntaSeguridadIA:
      "",

    clasificacionIAValida:
      false,

    usoFallbackIA:
      true,

    motivoFallbackIA:
      "La clasificación mediante IA falló técnicamente.",

    errorClasificacionIASanitizado,

    evaluacionIAUrgencia
  }
};

const entrada = $json;

const config =
  entrada.urgenciaConfig || {};

const usóClasificacionIA =
  Boolean(
    entrada.requiereClasificacionIA
  );

const mencionaAtencionReportada =
  Boolean(
    entrada.mencionaAtencionReportada
  );

// --------------------------------------------------
// Seleccionar resultado determinista o resultado IA
// --------------------------------------------------

let prioridadFinal =
  "";

let categoriaFinal =
  "";

let tipoContextoFinal =
  "";

let fuenteClasificacion =
  "";

let confianzaClasificacion =
  "";

let evidenciasFinales =
  [];

let preguntaSeguridad =
  "";

let usoFallback =
  false;

let motivoClasificacion =
  "";

if (usóClasificacionIA) {
  prioridadFinal =
    String(
      entrada.prioridadIA ||
      "prioridad_preventiva"
    ).trim();

  categoriaFinal =
    String(
      entrada.categoriaIA ||
      entrada.categoriaDeterminista ||
      "otra_senal_prioritaria"
    ).trim();

  tipoContextoFinal =
    String(
      entrada.tipoContextoIA ||
      "contexto_insuficiente"
    ).trim();

  confianzaClasificacion =
    String(
      entrada.confianzaIA ||
      "baja"
    ).trim();

  evidenciasFinales =
    Array.isArray(
      entrada.evidenciasIA
    )
      ? entrada.evidenciasIA
      : [];

  preguntaSeguridad =
    String(
      entrada.preguntaSeguridadIA ||
      ""
    ).trim();

  usoFallback =
    Boolean(
      entrada.usoFallbackIA
    );

  fuenteClasificacion =
    usoFallback
      ? "fallback"
      : "ia_controlada";

  motivoClasificacion =
    String(
      entrada.motivoFallbackIA ||
      entrada.evaluacionIAUrgencia
        ?.motivo_fallback ||
      "Clasificación controlada mediante IA."
    ).trim();
} else {
  prioridadFinal =
    String(
      entrada.prioridadDeterminista ||
      "sin_prioridad"
    ).trim();

  categoriaFinal =
    String(
      entrada.categoriaDeterminista ||
      ""
    ).trim();

  tipoContextoFinal =
    String(
      entrada.tipoContextoUrgencia ||
      "caso_actual"
    ).trim();

  confianzaClasificacion =
    prioridadFinal === "sin_prioridad"
      ? ""
      : "alta";

  evidenciasFinales =
    Array.isArray(
      entrada.evidenciasUrgencia
    )
      ? entrada.evidenciasUrgencia
      : [];

  preguntaSeguridad =
    "";

  fuenteClasificacion =
    "determinista";

  motivoClasificacion =
    String(
      entrada.evaluacionDeterministaUrgencia
        ?.motivo ||
      "Clasificación mediante reglas deterministas."
    ).trim();
}

// --------------------------------------------------
// Validación defensiva
// --------------------------------------------------

const prioridadesPermitidas = [
  "prioridad_inmediata",
  "prioridad_preventiva",
  "sin_prioridad"
];

const categoriasPermitidas = [
  "respiratoria",
  "neurologica",
  "alteracion_conciencia",
  "trauma",
  "hemorragia",
  "posible_intoxicacion",
  "urinaria",
  "termica",
  "gastrointestinal_grave",
  "reproductiva",
  "ocular_grave",
  "dolor_deterioro",
  "deterioro_subito",
  "otra_senal_prioritaria",
  "sin_categoria",
  ""
];

const contextosPermitidos = [
  "caso_actual",
  "caso_negado",
  "caso_historico",
  "pregunta_informativa",
  "situacion_hipotetica",
  "contexto_insuficiente",
  "atencion_reportada"
];

if (
  !prioridadesPermitidas.includes(
    prioridadFinal
  )
) {
  prioridadFinal =
    "prioridad_preventiva";

  fuenteClasificacion =
    "fallback";

  usoFallback =
    true;

  motivoClasificacion =
    "La prioridad final no era válida.";
}

if (
  !categoriasPermitidas.includes(
    categoriaFinal
  )
) {
  categoriaFinal =
    "otra_senal_prioritaria";
}

if (
  prioridadFinal !==
    "sin_prioridad" &&
  (
    !categoriaFinal ||
    categoriaFinal ===
      "sin_categoria"
  )
) {
  categoriaFinal =
    entrada.categoriaDeterminista ||
    "otra_senal_prioritaria";
}

if (
  !contextosPermitidos.includes(
    tipoContextoFinal
  )
) {
  tipoContextoFinal =
    "contexto_insuficiente";
}

// --------------------------------------------------
// Decisiones operativas
// --------------------------------------------------

const esPrioridadInmediata =
  prioridadFinal ===
  "prioridad_inmediata";

const esPrioridadPreventiva =
  prioridadFinal ===
  "prioridad_preventiva";

const esSenalPrioritaria =
  esPrioridadInmediata ||
  esPrioridadPreventiva;

const bloquearFlujoComercial =
  esSenalPrioritaria ||
  mencionaAtencionReportada;

const notificarInmediata =
  config
    .notificar_prioridad_inmediata
  !== false;

const notificarPreventiva =
  config
    .notificar_prioridad_preventiva
  !== false;

const requiereAvisoInterno =
  (
    esPrioridadInmediata &&
    notificarInmediata
  ) ||
  (
    esPrioridadPreventiva &&
    notificarPreventiva
  );

const requierePreguntaSeguridad =
  esPrioridadPreventiva &&
  Boolean(preguntaSeguridad);

const reglasActivadas =
  Array.isArray(
    entrada.reglasUrgenciaActivadas
  )
    ? entrada
        .reglasUrgenciaActivadas
    : [];

const clasificacionUrgencia = {
  prioridad:
    prioridadFinal,

  categoria:
    categoriaFinal,

  tipo_contexto:
    tipoContextoFinal,

  fuente:
    fuenteClasificacion,

  confianza:
    confianzaClasificacion,

  evidencias:
    evidenciasFinales,

  reglas_activadas:
    reglasActivadas,

  pregunta_seguridad:
    preguntaSeguridad,

  uso_fallback:
    usoFallback,

  motivo:
    motivoClasificacion,

  es_senal_prioritaria:
    esSenalPrioritaria,

  es_prioridad_inmediata:
    esPrioridadInmediata,

  es_prioridad_preventiva:
    esPrioridadPreventiva,

  menciona_atencion_reportada:
    mencionaAtencionReportada,

  bloquear_flujo_comercial:
    bloquearFlujoComercial,

  requiere_aviso_interno:
    requiereAvisoInterno
};

return {
  json: {
    ...entrada,

    prioridadUrgencia:
      prioridadFinal,

    categoriaUrgencia:
      categoriaFinal,

    tipoContextoUrgenciaFinal:
      tipoContextoFinal,

    fuenteClasificacionUrgencia:
      fuenteClasificacion,

    confianzaClasificacionUrgencia:
      confianzaClasificacion,

    evidenciasUrgenciaFinal:
      evidenciasFinales,

    preguntaSeguridadUrgencia:
      preguntaSeguridad,

    usoFallbackClasificacion:
      usoFallback,

    esPrioridadInmediata,
    esPrioridadPreventiva,
    esSenalPrioritaria,

    bloquearFlujoComercialUrgencia:
      bloquearFlujoComercial,

    requiereAvisoInternoUrgencia:
      requiereAvisoInterno,

    requierePreguntaSeguridadUrgencia:
      requierePreguntaSeguridad,

    clasificacionUrgencia
  }
};

const entrada = $json;

const config =
  entrada.urgenciaConfig || {};

const estadoPrevio =
  entrada.estadoUrgencia || {};

const zonaHoraria =
  String(
    config.zona_horaria ||
    "America/Santiago"
  );

const ventanaDeduplicacionMinutos =
  Math.max(
    Number(
      config.ventana_deduplicacion_minutos
    ) || 10,
    1
  );

const DateTime =
  $now.constructor;

const ahora =
  $now.setZone(zonaHoraria);

const ahoraIso =
  ahora.toISO();

// --------------------------------------------------
// Utilidades
// --------------------------------------------------

const limpiarId = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9_-]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "")
    .slice(0, 40);

const crearId = (prefijo) => {
  const clinic =
    limpiarId(
      entrada.clinic_id ||
      "clinica"
    );

  const session =
    limpiarId(
      entrada.session_id ||
      "sesion"
    );

  const timestamp =
    ahora.toFormat(
      "yyyyLLddHHmmssSSS"
    );

  const aleatorio =
    Math.random()
      .toString(36)
      .slice(2, 10);

  return [
    prefijo,
    clinic,
    session,
    timestamp,
    aleatorio
  ].join("_");
};

const interpretarFecha = (valor) => {
  const texto =
    String(valor || "").trim();

  if (!texto) {
    return null;
  }

  const fecha =
    DateTime.fromISO(
      texto,
      {
        zone: zonaHoraria
      }
    );

  return fecha.isValid
    ? fecha
    : null;
};

// --------------------------------------------------
// Clasificación actual
// --------------------------------------------------

const prioridadActual =
  String(
    entrada.prioridadUrgencia ||
    "prioridad_preventiva"
  ).trim();

const categoriaActual =
  String(
    entrada.categoriaUrgencia ||
    "otra_senal_prioritaria"
  ).trim();

const tipoContextoActual =
  String(
    entrada.tipoContextoUrgenciaFinal ||
    "caso_actual"
  ).trim();

const fuenteClasificacion =
  String(
    entrada.fuenteClasificacionUrgencia ||
    "determinista"
  ).trim();

const confianzaClasificacion =
  String(
    entrada.confianzaClasificacionUrgencia ||
    ""
  ).trim();

const preguntaSeguridad =
  String(
    entrada.preguntaSeguridadUrgencia ||
    ""
  ).trim();

const reglasActivadas =
  Array.isArray(
    entrada.reglasUrgenciaActivadas
  )
    ? entrada.reglasUrgenciaActivadas
    : [];

const evidencias =
  Array.isArray(
    entrada.evidenciasUrgenciaFinal
  )
    ? entrada.evidenciasUrgenciaFinal
    : [];

// --------------------------------------------------
// Estado anterior y deduplicación
// --------------------------------------------------

const episodeIdPrevio =
  String(
    estadoPrevio.episode_id_activo ||
    ""
  ).trim();

const alertIdPrevio =
  String(
    estadoPrevio.alert_id_ultimo ||
    ""
  ).trim();

const estadoEpisodioPrevio =
  String(
    estadoPrevio.estado_episodio ||
    "sin_episodio"
  ).trim();

const prioridadPrevia =
  String(
    estadoPrevio.prioridad_actual ||
    ""
  ).trim();

const categoriaPrevia =
  String(
    estadoPrevio.categoria_actual ||
    ""
  ).trim();

const episodioActivoPrevio =
  Boolean(episodeIdPrevio) &&
  [
    "activo_preventivo",
    "activo_inmediato"
  ].includes(
    estadoEpisodioPrevio
  );

const ultimaAlerta =
  interpretarFecha(
    estadoPrevio.ultima_alerta_at
  );

const minutosDesdeUltimaAlerta =
  ultimaAlerta
    ? ahora
        .diff(
          ultimaAlerta,
          "minutes"
        )
        .minutes
    : null;

const dentroVentanaDeduplicacion =
  episodioActivoPrevio &&
  minutosDesdeUltimaAlerta !== null &&
  minutosDesdeUltimaAlerta >= 0 &&
  minutosDesdeUltimaAlerta <=
    ventanaDeduplicacionMinutos;

const escalaPreventivaAInmediata =
  episodioActivoPrevio &&
  prioridadPrevia ===
    "prioridad_preventiva" &&
  prioridadActual ===
    "prioridad_inmediata";

const nuevaCategoriaInmediata =
  episodioActivoPrevio &&
  prioridadActual ===
    "prioridad_inmediata" &&
  Boolean(categoriaPrevia) &&
  categoriaActual !== categoriaPrevia;

const esEscalamiento =
  escalaPreventivaAInmediata ||
  nuevaCategoriaInmediata;

// --------------------------------------------------
// Determinar evento
// --------------------------------------------------

let tipoEvento = "";
let resultadoDeduplicacion = "";
let episodeId = "";
let requiereAvisoInternoFinal = false;

const avisoPermitidoPorConfiguracion =
  Boolean(
    entrada.requiereAvisoInternoUrgencia
  );

if (!episodioActivoPrevio) {
  tipoEvento =
    "apertura";

  resultadoDeduplicacion =
    "nueva";

  episodeId =
    crearId("episode");

  requiereAvisoInternoFinal =
    avisoPermitidoPorConfiguracion;
} else if (esEscalamiento) {
  tipoEvento =
    "escalacion";

  resultadoDeduplicacion =
    "escalada";

  episodeId =
    episodeIdPrevio;

  requiereAvisoInternoFinal =
    avisoPermitidoPorConfiguracion;
} else if (
  dentroVentanaDeduplicacion
) {
  tipoEvento =
    "actualizacion";

  resultadoDeduplicacion =
    "agrupada_sin_nuevo_aviso";

  episodeId =
    episodeIdPrevio;

  requiereAvisoInternoFinal =
    false;
} else {
  tipoEvento =
    "actualizacion";

  resultadoDeduplicacion =
    "reaviso_fuera_de_ventana";

  episodeId =
    episodeIdPrevio;

  requiereAvisoInternoFinal =
    avisoPermitidoPorConfiguracion;
}

const alertId =
  crearId("alert");

// --------------------------------------------------
// Plantilla pública
// --------------------------------------------------

const instruccionesPorCategoria = {
  posible_intoxicacion:
    " No provoques el vómito ni administres medicamentos sin indicación veterinaria. Si existe un envase o etiqueta de la sustancia, llévalo contigo.",

  trauma:
    " Evita mover innecesariamente a la mascota y trasládala de forma segura, siempre que hacerlo no te ponga en riesgo.",

  termica:
    " Retira a la mascota de la fuente de calor y busca atención veterinaria inmediata. No retrases el traslado esperando una respuesta por este chat.",

  hemorragia:
    " No administres medicamentos por cuenta propia."
};

let plantillaPublicaId = "";
let respuestaPublica = "";

if (
  prioridadActual ===
  "prioridad_inmediata"
) {
  plantillaPublicaId =
    instruccionesPorCategoria[
      categoriaActual
    ]
      ? `urgencia_inmediata_${categoriaActual}_v1`
      : "urgencia_inmediata_general_v1";

  respuestaPublica =
    "Lo que describes podría requerir atención veterinaria urgente. " +
    "Comunícate ahora con la clínica o acude a un servicio veterinario de urgencia. " +
    "No esperes una confirmación de agenda ni una respuesta por este chat antes de buscar atención." +
    (
      instruccionesPorCategoria[
        categoriaActual
      ] || ""
    );
} else {
  plantillaPublicaId =
    "urgencia_preventiva_general_v1";

  respuestaPublica =
    "Lo que describes puede ser preocupante y conviene que sea evaluado cuanto antes. " +
    "Contacta ahora a la clínica o a un servicio veterinario. " +
    "No continúes con una reserva normal mientras persista esta situación y no esperes una respuesta por este chat antes de buscar atención.";

  if (preguntaSeguridad) {
    respuestaPublica +=
      ` ${preguntaSeguridad}`;
  }
}

// --------------------------------------------------
// Estado actualizado
// --------------------------------------------------

const estadoEpisodioNuevo =
  prioridadActual ===
  "prioridad_inmediata"
    ? "activo_inmediato"
    : "activo_preventivo";

const estadoUrgenciaActualizado = {
  state_key:
    estadoPrevio.state_key ||
    entrada.state_key_urgencia,

  clinic_id:
    entrada.clinic_id,

  session_id:
    entrada.session_id,

  canal_publico:
    estadoPrevio.canal_publico ||
    entrada.channel ||
    config.canal_publico ||
    "streamlit",

  mensajes_recientes_json:
    estadoPrevio.mensajes_recientes_json ||
    JSON.stringify(
      entrada.mensajesContextoUrgencia ||
      []
    ),

  ultimo_mensaje_usuario:
    String(
      entrada.message || ""
    ).trim(),

  ultima_actividad_at:
    ahoraIso,

  episode_id_activo:
    episodeId,

  alert_id_ultimo:
    alertId,

  estado_episodio:
    estadoEpisodioNuevo,

  prioridad_actual:
    prioridadActual,

  categoria_actual:
    categoriaActual,

  pregunta_seguridad_pendiente:
    preguntaSeguridad,

  pregunta_seguridad_at:
    preguntaSeguridad
      ? ahoraIso
      : "",

  ultima_alerta_at:
    ahoraIso,

  ultima_notificacion_at:
    String(
      estadoPrevio
        .ultima_notificacion_at ||
      ""
    ),

  expira_contexto_at:
    estadoPrevio.expira_contexto_at ||
    entrada.estadoUrgencia
      ?.expira_contexto_at ||
    "",

  created_at:
    estadoPrevio.created_at ||
    ahoraIso,

  updated_at:
    ahoraIso
};

// --------------------------------------------------
// Registro histórico
// --------------------------------------------------

const clasificacionJson =
  JSON.stringify({
    fuente:
      fuenteClasificacion,

    confianza:
      confianzaClasificacion,

    tipo_contexto:
      tipoContextoActual,

    reglas_activadas:
      reglasActivadas,

    evidencias,

    pregunta_seguridad:
      preguntaSeguridad,

    uso_fallback:
      Boolean(
        entrada
          .usoFallbackClasificacion
      )
  });

const alertaUrgencia = {
  alert_id:
    alertId,

  episode_id:
    episodeId,

  parent_alert_id:
    alertIdPrevio,

  tipo_evento:
    tipoEvento,

