    estadoUrgenciaActualizado
      .canal_publico,

  created_at:
    ahoraIso,

  mensaje_actual:
    String(
      entrada.message || ""
    ).trim(),

  contexto_reciente_json:
    estadoUrgenciaActualizado
      .mensajes_recientes_json,

  tipo_contexto:
    tipoContextoActual,

  prioridad:
    prioridadActual,

  categoria:
    categoriaActual,

  clasificacion_json:
    clasificacionJson,

  requiere_aviso_interno:
    requiereAvisoInternoFinal,

  resultado_deduplicacion:
    resultadoDeduplicacion,

  plantilla_publica_id:
    plantillaPublicaId,

  respuesta_publica:
    respuestaPublica,

  estado_ejecucion:
    "pendiente_operaciones_internas"
};

return {
  json: {
    ...entrada,

