const fuente =
  $("Preparar episodio y alerta urgencia")
    .first()
    .json;

const fila =
  fuente.estadoUrgenciaActualizado;

if (
  !fila ||
  typeof fila !== "object" ||
  Array.isArray(fila)
) {
  throw new Error(
    "No fue posible preparar el estado de urgencia."
  );
}

return {
  json: {
    ...fila
  }
};

const fuente =
  $("Preparar episodio y alerta urgencia")
    .first()
    .json;

const alertaBase =
  fuente.alertaUrgencia;

if (
  !alertaBase ||
  typeof alertaBase !== "object" ||
  Array.isArray(alertaBase)
) {
  throw new Error(
    "No fue posible preparar la alerta de urgencia."
  );
}

// --------------------------------------------------
// Funciones auxiliares
// --------------------------------------------------

const convertirTextoSeguro = (valor) => {
  if (
    typeof valor === "string"
  ) {
    return valor.trim();
  }

  if (
    valor &&
    typeof valor === "object"
  ) {
    try {
      return JSON.stringify(
        valor
      );
    } catch {
      return "";
    }
  }

  return "";
};

const sanitizarError = (valor) =>
  String(
    valor || ""
  )
    .replace(
      /https?:\/\/\S+/gi,
      "[URL_REDACTADA]"
    )
    .replace(
      /\bBearer\s+\S+/gi,
      "[TOKEN_REDACTADO]"
    )
    .replace(
      /\b[a-z0-9_\-]{32,}\b/gi,
      "[VALOR_REDACTADO]"
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim()
    .slice(
      0,
      300
    );

// --------------------------------------------------
// Detectar si falló el guardado del estado
//
// La salida Error puede llegar como:
// { error: "texto" }
// o como:
// { error: { message: "texto" } }
// --------------------------------------------------

const candidatosError = [
  typeof $json.error ===
  "string"
    ? $json.error
    : "",

  $json.error?.message,

  $json.error?.description,

  $json.error?.cause?.message,

  $json
    .error
    ?.response
    ?.data
    ?.error
    ?.message,

  $json
    .error
    ?.response
    ?.data
    ?.message,

  $json.error_message,

  $json.errorMessage,

  $json
    .executionError
    ?.message,

  $json
    .nodeExecutionError
    ?.message
];

const errorRecibido =
  candidatosError
    .map(
      convertirTextoSeguro
    )
    .find(Boolean) ||
  "";

const falloGuardarEstadoUrgencia =
  Boolean(
    errorRecibido ||
    $json.error ||
    $json.error_message ||
    $json.errorMessage
  );

const errorGuardarEstadoUrgenciaSanitizado =
  falloGuardarEstadoUrgencia
    ? sanitizarError(
        errorRecibido ||
        "sin_detalle_tecnico"
      )
    : "";

// --------------------------------------------------
// Preparar fila histórica
// --------------------------------------------------

const estadoEjecucion =
  falloGuardarEstadoUrgencia
    ? "fallo_estado_pendiente_notificacion"
    : "estado_guardado_pendiente_notificacion";

const filaAlerta = {
  alert_id:
    alertaBase.alert_id,

  episode_id:
    alertaBase.episode_id,

  parent_alert_id:
    alertaBase.parent_alert_id,

  tipo_evento:
    alertaBase.tipo_evento,

  clinic_id:
    alertaBase.clinic_id,

  session_id:
    alertaBase.session_id,

  canal_publico:
    alertaBase.canal_publico,

  created_at:
    alertaBase.created_at,

  mensaje_actual:
    alertaBase.mensaje_actual,

  contexto_reciente_json:
    alertaBase.contexto_reciente_json,

  tipo_contexto:
    alertaBase.tipo_contexto,

  prioridad:
    alertaBase.prioridad,

  categoria:
    alertaBase.categoria,

  clasificacion_json:
    alertaBase.clasificacion_json,

  requiere_aviso_interno:
    Boolean(
      alertaBase.requiere_aviso_interno
    ),

  resultado_deduplicacion:
    alertaBase.resultado_deduplicacion,

  plantilla_publica_id:
    alertaBase.plantilla_publica_id,

  respuesta_publica:
    alertaBase.respuesta_publica,

  estado_ejecucion:
    estadoEjecucion
};

return {
  json: {
    ...filaAlerta,

    falloGuardarEstadoUrgencia,
    errorGuardarEstadoUrgenciaSanitizado
  }
};

// --------------------------------------------------
// Entrada recibida desde Registrar alerta urgencia
//
// Esta normalización admite las dos estructuras:
// 1. { alert_id: "...", ... }
// 2. { json: { alert_id: "...", ... }, pairedItem: ... }
// --------------------------------------------------

const entradaBruta =
  $json &&
  typeof $json === "object" &&
  !Array.isArray($json)
    ? $json
    : {};

const desenvolverJson = (valor) => {
  let actual = valor;

  for (
    let nivel = 0;
    nivel < 4;
    nivel += 1
  ) {
    const tieneJsonAnidado =
      actual &&
      typeof actual === "object" &&
      !Array.isArray(actual) &&
      actual.json &&
      typeof actual.json === "object" &&
      !Array.isArray(actual.json);

    if (
      !tieneJsonAnidado
    ) {
      break;
    }

    actual =
      actual.json;
  }

  return (
    actual &&
    typeof actual === "object" &&
    !Array.isArray(actual)
  )
    ? actual
    : {};
};

const resultadoRegistro =
  desenvolverJson(
    entradaBruta
  );

// Datos preparados antes del intento de registro.
// Se conservan aunque Data Table falle.
const entradaOriginal =
  $("Preparar fila alerta urgencia")
    .first()
    .json;

// --------------------------------------------------
// Funciones auxiliares
// --------------------------------------------------

const convertirTextoSeguro = (valor) => {
  if (
    typeof valor === "string"
  ) {
    return valor.trim();
  }

  if (
    valor &&
    typeof valor === "object"
  ) {
    try {
      return JSON.stringify(
        valor
      );
    } catch {
      return "";
    }
  }

  return "";
};

const sanitizarError = (valor) => {
  const texto = String(
    valor ||
    "sin_detalle_tecnico"
  )
    .replace(
      /https?:\/\/\S+/gi,
      "[URL_REDACTADA]"
    )
    .replace(
      /\bBearer\s+\S+/gi,
      "[TOKEN_REDACTADO]"
    )
    .replace(
      /\b[a-z0-9_\-]{32,}\b/gi,
      "[VALOR_REDACTADO]"
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

  return texto.slice(
    0,
    300
  );
};

const esVerdadero = (valor) => {
  if (
    valor === true ||
    valor === 1
  ) {
    return true;
  }

  const texto = String(
    valor ?? ""
  )
    .trim()
    .toLowerCase();

  return (
    texto === "true" ||
    texto === "1" ||
    texto === "si" ||
    texto === "sí"
  );
};

const convertirNumero = (valor) => {
  if (
    valor === undefined ||
    valor === null ||
    String(valor).trim() === ""
  ) {
    return null;
  }

  const numero =
    Number(valor);

  return Number.isFinite(
    numero
  )
    ? numero
    : null;
};

// --------------------------------------------------
// Fuentes posibles para detectar errores
//
// Se revisa tanto la estructura desenvuelta como
// la entrada bruta. Nunca se usa el campo message,
// porque podría contener el mensaje del usuario.
// --------------------------------------------------

const fuentesResultado = [
  resultadoRegistro,
  entradaBruta
];

const candidatosError =
  fuentesResultado.flatMap(
    (fuente) => [
      fuente
        ?.error
        ?.message,

      fuente
        ?.error
        ?.description,

      fuente
        ?.error
        ?.cause
        ?.message,

      fuente
        ?.error
        ?.response
        ?.data
        ?.error
        ?.message,

      fuente
        ?.error
        ?.response
        ?.data
        ?.message,

      fuente
        ?.response
        ?.data
        ?.error
        ?.message,

      fuente
        ?.response
        ?.data
        ?.message,

      fuente
        ?.executionError
        ?.message,

      fuente
        ?.nodeExecutionError
        ?.message,

      fuente
        ?.cause
        ?.message,

      fuente
        ?.details
        ?.message,

      fuente
        ?.errorMessage,

      typeof fuente?.error ===
      "string"
        ? fuente.error
        : ""
    ]
  );

const errorTecnicoEncontrado =
  candidatosError
    .map(
      convertirTextoSeguro
    )
    .find(Boolean) ||
  "";

const posiblesCodigosHttp =
  fuentesResultado
    .flatMap(
      (fuente) => [
        fuente
          ?.statusCode,

        fuente
          ?.httpCode,

        fuente
          ?.error
          ?.statusCode,

        fuente
          ?.error
          ?.status,

        fuente
          ?.error
          ?.response
          ?.status
      ]
    )
    .map(
      convertirNumero
    )
    .filter(
      (valor) =>
        valor !== null
    );

const hayCodigoHttpError =
  posiblesCodigosHttp.some(
    (codigo) =>
      codigo >= 400
  );

const hayErrorTecnico =
  Boolean(
    errorTecnicoEncontrado ||
    hayCodigoHttpError
  );

// --------------------------------------------------
// Confirmación del registro
// --------------------------------------------------

const alertIdEsperado =
  String(
    entradaOriginal
      .alert_id ||
    entradaOriginal
      .alertId ||
    entradaOriginal
      .alertaUrgencia
      ?.alert_id ||
    ""
  ).trim();

const alertIdRecibido =
  String(
    resultadoRegistro
      .alert_id ||
    resultadoRegistro
      .alertId ||
    entradaBruta
      .alert_id ||
    entradaBruta
      .alertId ||
    entradaBruta
      .json
      ?.alert_id ||
    ""
  ).trim();

const coincideAlertId =
  Boolean(
    alertIdRecibido &&
    (
      !alertIdEsperado ||
      alertIdEsperado ===
        alertIdRecibido
    )
  );

const registroAlertaConfirmado =
  Boolean(
    coincideAlertId &&
    !hayErrorTecnico
  );

const falloRegistroAlerta =
  !registroAlertaConfirmado;

const errorRegistroAlertaSanitizado =
  falloRegistroAlerta
    ? sanitizarError(
        errorTecnicoEncontrado ||
        "sin_detalle_tecnico"
      )
    : "";

// --------------------------------------------------
// Mantener la decisión de notificación aunque falle
// el registro inicial de la alerta
// --------------------------------------------------

const fuentesAvisoInterno = [
  entradaOriginal
    .requiereAvisoInternoFinal,

  entradaOriginal
    .requiereAvisoInternoUrgencia,

  entradaOriginal
    .requiere_aviso_interno,

  entradaOriginal
    .alertaUrgencia
    ?.requiere_aviso_interno,

  entradaOriginal
    .clasificacionUrgencia
    ?.requiere_aviso_interno,

  resultadoRegistro
    .requiereAvisoInternoFinal,

  resultadoRegistro
    .requiereAvisoInternoUrgencia,

  resultadoRegistro
    .requiere_aviso_interno,

  resultadoRegistro
    .alertaUrgencia
    ?.requiere_aviso_interno,

  resultadoRegistro
    .clasificacionUrgencia
    ?.requiere_aviso_interno,

  entradaBruta
    .requiereAvisoInternoFinal,

  entradaBruta
    .requiereAvisoInternoUrgencia,

  entradaBruta
    .requiere_aviso_interno,

  entradaBruta
    .json
    ?.requiere_aviso_interno
];

const requiereAvisoInternoFinal =
  fuentesAvisoInterno.some(
    esVerdadero
  );

// --------------------------------------------------
// Estado previo a la notificación
// --------------------------------------------------

let estadoInternoPreNotificacion =
  "";

if (
  registroAlertaConfirmado &&
  requiereAvisoInternoFinal
) {
  estadoInternoPreNotificacion =
    "alerta_registrada_pendiente_aviso";
} else if (
  registroAlertaConfirmado &&
  !requiereAvisoInternoFinal
) {
  estadoInternoPreNotificacion =
    "alerta_registrada_sin_aviso";
} else if (
  !registroAlertaConfirmado &&
  requiereAvisoInternoFinal
) {
  estadoInternoPreNotificacion =
    "alerta_no_registrada_pendiente_aviso";
} else {
  estadoInternoPreNotificacion =
    "alerta_no_registrada_sin_aviso";
}

// --------------------------------------------------
// Salida
// --------------------------------------------------

return {
  json: {
    ...entradaOriginal,

    registroAlertaConfirmado,
    falloRegistroAlerta,

    errorRegistroAlertaSanitizado,

    requiereAvisoInternoFinal,

    estadoInternoPreNotificacion
  }
};

const entrada = $json;

