    registroIntentoPendienteConfirmado:
      !falloRegistroIntentoPendiente,

    falloRegistroIntentoPendiente,

    errorRegistroIntentoPendienteSanitizado,

    estadoPrevioEnvioTelegram:
      falloRegistroIntentoPendiente
        ? "registro_pendiente_fallido"
        : "registro_pendiente_confirmado"
  }
};

const fuente =
  $("Consolidar intento pendiente Telegram")
    .first()
    .json;

const config =
  fuente.urgenciaConfig || {};

const zonaHoraria =
  String(
    config.zona_horaria ||
    "America/Santiago"
  );

const ahoraIso =
  $now
    .setZone(zonaHoraria)
    .toISO();

const sanitizarError = (valor) =>
  String(valor || "")
    .replace(
      /https?:\/\/\S+/gi,
      "[URL_REDACTADA]"
    )
    .replace(
      /\b(bearer\s+)?[a-z0-9_\-]{32,}\b/gi,
      "[VALOR_REDACTADO]"
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim()
    .slice(0, 300);

const errorObjeto =
  $json.error ||
  null;

const codigoHttp =
  Number(
    errorObjeto?.httpCode ||
    errorObjeto?.statusCode ||
    errorObjeto?.status ||
    $json.statusCode ||
    $json.httpCode ||
    0
  );

const descripcionError =
  errorObjeto?.message ||
  errorObjeto?.description ||
  errorObjeto?.cause?.message ||
  $json.error_message ||
  $json.description ||
  (
    $json.ok === false
      ? JSON.stringify($json)
      : ""
  );

const falloEnvioTelegram =
  Boolean(
    errorObjeto ||
    $json.error_message ||
    $json.ok === false
  );

const errorTelegramSanitizado =
  falloEnvioTelegram
    ? sanitizarError(
        descripcionError ||
        "error_envio_telegram"
      )
    : "";

const textoErrorNormalizado =
  errorTelegramSanitizado
    .toLowerCase();

const erroresDefinitivos = [
  "unauthorized",
  "forbidden",
  "bot was blocked",
  "chat not found",
  "bad request",
  "invalid token",
  "user is deactivated"
];

const erroresTransitorios = [
  "timeout",
  "timed out",
  "temporary",
  "temporarily",
  "connection",
  "network",
  "socket",
  "econnreset",
  "etimedout",
  "rate limit",
  "too many requests",
  "service unavailable",
  "bad gateway",
  "gateway timeout"
];

const codigoTransitorio = [
  408,
  425,
  429,
  500,
  502,
  503,
  504
].includes(codigoHttp);

const contieneErrorDefinitivo =
  erroresDefinitivos.some(
    (texto) =>
      textoErrorNormalizado.includes(texto)
  );

const contieneErrorTransitorio =
  erroresTransitorios.some(
    (texto) =>
      textoErrorNormalizado.includes(texto)
  );

const reintentable =
  falloEnvioTelegram &&
  !contieneErrorDefinitivo &&
  (
    codigoTransitorio ||
    contieneErrorTransitorio
  );

const providerMessageRef =
  !falloEnvioTelegram
    ? String(
        $json.message_id ||
        $json.result?.message_id ||
        $json.data?.message_id ||
        ""
      )
    : "";

const retryAfter =
  Number(
    errorObjeto?.response?.parameters?.retry_after ||
    errorObjeto?.parameters?.retry_after ||
    $json.parameters?.retry_after ||
    0
  );

const segundosEsperaReintento =
  reintentable
    ? Math.min(
        Math.max(
          retryAfter || 3,
          3
        ),
        30
