  fila?.cause?.message,
  fila?.errorMessage,
  fila?.error_message,
  typeof fila?.error === "string"
    ? fila.error
    : ""
];

const errorTecnico =
  candidatosError
    .map(textoSeguro)
    .find(Boolean) ||
  "";

const camposVerificados = [
  "alert_id",
  "episode_id",
  "clinic_id",
  "session_id",
  "tipo_evento",
  "estado_ejecucion"
];

const camposNoCoincidentes =
  camposVerificados.filter(
    (campo) =>
      String(
        fila?.[campo] ?? ""
      ).trim() !==
      String(
        esperado?.[campo] ?? ""
      ).trim()
  );

const filaEncontrada =
  Boolean(
    String(
      fila?.alert_id || ""
    ).trim()
  );

const registroAtencionReportadaConfirmado =
  filaEncontrada &&
  camposNoCoincidentes.length === 0 &&
  !errorTecnico;

const falloRegistrarAtencionReportada =
  !registroAtencionReportadaConfirmado;

let motivoFallo = "";

if (falloRegistrarAtencionReportada) {
  if (errorTecnico) {
    motivoFallo =
      errorTecnico;
  } else if (!filaEncontrada) {
    motivoFallo =
      "evento_atencion_reportada_no_encontrado";
  } else {
    motivoFallo =
      `campos_no_coincidentes:${camposNoCoincidentes.join(",")}`;
  }
}

return {
  json: {
    alert_id:
      String(
        esperado?.alert_id || ""
      ),

    episode_id:
      String(
        esperado?.episode_id || ""
      ),

    clinic_id:
      String(
        esperado?.clinic_id || ""
      ),

    session_id:
      String(
        esperado?.session_id || ""
      ),

    registroAtencionReportadaConfirmado,

    falloRegistrarAtencionReportada,

    errorRegistrarAtencionReportadaSanitizado:
      falloRegistrarAtencionReportada
        ? sanitizarError(
            motivoFallo
          )
        : "",

    estadoCierreAtencionReportada:
      registroAtencionReportadaConfirmado
        ? "registro_atencion_reportada_confirmado"
        : "registro_atencion_reportada_fallido",

    filaAtencionReportadaEncontrada:
      filaEncontrada,

    camposNoCoincidentes,

    cierreInternoProcesado:
      true
  }
};
